INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('10mg-cover-me-in-leaves', 139901, '2020-10-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5uve.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4kjw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '10mg: Cover Me In Leaves', 'Cover Me In Leaves is an experimental work of interactive horror fiction, about bright minds, and the end of all things. Fresh out of high school, with no prospects or aspirations, you''ve remained here in your small town. Everyone you knew and loved has moved on for better things. You''re alone. So you get your first tattoo. And then the trees start calling.' FROM games WHERE igdb_id = 139901 ON CONFLICT (game_id, language_code) DO NOTHING;
