INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warcraft III: Reforged', 'Warcraft III: Reforged is a stunning reimagining of the revolutionary real-time strategy game that laid the foundation for Azeroth''s most epic stories. It is a remake in the truest sense, featuring a thorough visual overhaul, a suite of contemporary social and matchmaking features, and more. Command the Night Elves, Undead, Orcs, and Humans as alliances shift and armies clash in this timeless real-time strategy game.' FROM games WHERE igdb_id = 111650 ON CONFLICT (game_id, language_code) DO NOTHING;
