INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atlas-rogues', 140950, '2020-11-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2keo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrfu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atlas Rogues', 'Time is ticking in the city of Atlas. It’s up to you to prevent the Reactor from melting down. Recruit your team from an ever-growing roster of fierce freelancers to recover the Reactor keys from the evil Trusts. Experience rogue-lite gameplay like never before as you complete dynamic missions and navigate deadly combat zones to kill the Necrolancers while evading their attacks. Fail to stop the meltdown and watch as time loops back, filling every new run with unique content. Whether playing solo or with a group of friends in exhilarating co-op, every move matters in turn-based PvE combat, so strategize wisely how to grow your power and gather the intel you need to defeat the Trust bosses. Your squad has to work together to survive together in this thrilling addition to the Atlas universe.' FROM games WHERE igdb_id = 140950 ON CONFLICT (game_id, language_code) DO NOTHING;
