INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ninja-turdle', 128108, '2020-02-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2m9m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrc0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Turdle', 'Ninja Turdle sets out to destroy all the parasites in order to save his creator, Steve.  Ninja Turdle is a 2D Metroidvania platformer that involves exploring all through Steve''s body destroying parasites.  # Story  Get ready to fling corn infused turds at everything that moves as you help Ninja Turdle make his way through Steve''s parasite infected body. But hurry up before Steve is completely consumed by flesh eating parasites.  # Game Play  - Explore over 175 inter-connected chambers ranging from Steve''s stomach, intestines, heart, lungs, toilet, and even deep into his brain.  - Find masks and power-ups that offer new abilities such as the blood mask, wall climb, anti-acid pills, dung beetle, and many more.  - Toss chunks of turds at parasites.  - Infuse your turds with Corn to launch even more powerful attacks.  - Explore deep enough and maybe even learn the secret art of "Shoryupoo" and "Hadoupoo".  - Three different difficulty modes.  - Different techno tracks for each area.  - 45 Steam achievements.' FROM games WHERE igdb_id = 128108 ON CONFLICT (game_id, language_code) DO NOTHING;
