INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fast & Furious: Crossroads', 'Gear up for an epic new chapter in the Fast & Furious saga with high-speed heists, cinematic nonstop action, and adrenaline-fueled stunts in exotic locations. Join longtime family and a tough new crew to hunt down an international crime syndicate and bring them to street justice. Less than 2 years after its release, it was announced that Fast & Furious: Crossroads would be delisted from all stores on 29th April 2022.' FROM games WHERE igdb_id = 127356 ON CONFLICT (game_id, language_code) DO NOTHING;
