INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Giraffe and Annika', 'Giraffe and Annika is a 3D adventure game for PC where you follow along with the cat eared girl Annika as she explores the mysterious island of Spika. Each dungeon is guarded by a boss where Annika will need to defeated through a music-based battle system and fully synched animations. The game system and effects are all fully synched with the music. Help Annika find her lost memories through her adventures on the island!' FROM games WHERE igdb_id = 101220 ON CONFLICT (game_id, language_code) DO NOTHING;
