INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Dark Crystal: Age of Resistance Tactics', 'In The Dark Crystal: Age of Resistance Tactics, lead the heroic Gelfling to restore light to the world of Thra! Experience everything the fantasy world has to offer by playing through–and going beyond–the events of the Netflix series. Encounter never-seen-before playable characters, stories, and environments. Over the course of 80 unique turn-based campaign battles taking place across the lands of Thra, recruit new allies and customize their forces by assigning them jobs and outfitting them with new equipment.' FROM games WHERE igdb_id = 119384 ON CONFLICT (game_id, language_code) DO NOTHING;
