INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solitaire 3D', 'Enjoy over 100 different solitaire games (including all your favorites: Spider, Pyramid, FreeCell, Klondike, Tri-Peaks etc.), multiple card decks (including the unique 4 color card deck), online high scores, statistics, and much more. Compete with players across the world with online high scores for each game! With emphasis on ease-of-play and smooth beautiful graphics, Solitaire 3D is the perfect solitaire partner for all.' FROM games WHERE igdb_id = 89738 ON CONFLICT (game_id, language_code) DO NOTHING;
