INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Urban Trial Tricky', 'Urban Trial Tricky is a light-hearted game mixing tricks, platforming and racing. Easy gameplay, yet deep and rewarding. Set in a cartoon-style city, game features dynamic tricks system that enables players to finesse the most exciting moves and combos on a motorbike. 3 modes, over 30 levels and a vast amount of outstanding customization options make Urban Trial Tricky infinite and varied experience. And all of this in smooth 60 FPS!' FROM games WHERE igdb_id = 134783 ON CONFLICT (game_id, language_code) DO NOTHING;
