INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Not Tonight: Take Back Control Edition', 'Not Tonight is a post-Brexit management game, fusing a time-pressure RPG with a politically charged story where every decision matters. Will you join the resistance and fight the regime -- or keep your head down and hope that one day this will all be a distant memory? Not Tonight: One Love is a full, extra chapter that follows on from the main Not Tonight storyline. King''s Head Dave has had just about enough of everything happening in Britain, and has decided to pack up and move to France, in the hope of finding true love.' FROM games WHERE igdb_id = 121156 ON CONFLICT (game_id, language_code) DO NOTHING;
