INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Half-Life: Alyx', 'Half-Life: Alyx is Valve’s VR return to the Half-Life series. It’s the story of an impossible fight against a vicious alien race known as the Combine, set between the events of Half-Life and Half-Life 2. Alyx Vance and her father Eli mount an early resistance to the Combine''s brutal occupation of Earth.' FROM games WHERE igdb_id = 126098 ON CONFLICT (game_id, language_code) DO NOTHING;
