INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D4DJ Groovy Mix', '"D4 FES", a DJ festival that is the stuff of legends. Inspired by this festival, Japan too experiences a new dawn in DJ culture. As DJs becomes the main method for people to experience music, performers called "DJ Units" have begun to appear. As a culture that can be enjoyed by anyone, young or old, DJing has become an indispensable music genre.' FROM games WHERE igdb_id = 130305 ON CONFLICT (game_id, language_code) DO NOTHING;
