INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curse of Anabelle', 'Curse of Anabelle is a story driven adventure-horror/puzzle game which players can experience in the first person perspective. The storyline is based on real world myths and legends.  Curse of Anabelle offers a new take on the adventure/horror genre while being connected to real-world legends. In this adventure, Nathan will uncover a mystery that dates back to 10th century B.C. and face dark forces even that are even older than the Earth itself.' FROM games WHERE igdb_id = 122826 ON CONFLICT (game_id, language_code) DO NOTHING;
