INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('project-genesis', 114409, '2020-05-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2sc6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arefg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Genesis', 'Embark on a sci-fi journey in this player versus player shooter. In Project Genesis, you''ll get to pilot a powerful space-faring battle craft and as an avatar in first-person, giving you an intense and exciting gameplay experience. Set in the future and half galaxy away, an AI rebellion has sparked a dangerous conflict that threatens to consume everything in its path. As unit with a specialized breach-and-board assault pod, you''ll dramatically transition between the space theater and close quarters FPS combat as you fight aboard titanic capital ships. With fast-paced combat, stunning graphics, and immersive sound design, this game is like Call of Duty in space. It''s designed for players who love first-person shooters in a science fiction universe Project Genesis is currently in pre-alpha, so you can watch it develop and contribute to its evolution. Get ready for an intense battle that will push you to your limits. The fate of the galaxy is in your hands. Are you ready to take on the challenge?' FROM games WHERE igdb_id = 114409 ON CONFLICT (game_id, language_code) DO NOTHING;
