INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Das Balkonzimmer', 'Discover the balcony room in a completely new 3D world. Move with your unique character. Discover the expanse of the balcony room, its facets and niches. Shoot with your weapon and move objects through the game''s physics! Fling them off the balcony or across the room, whatever you want! You can experience the game in first person as well as in third person, depending on your wishes.' FROM games WHERE igdb_id = 141415 ON CONFLICT (game_id, language_code) DO NOTHING;
