INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pixeljunk-eden-2', 131872, '2020-12-09', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co229n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc06.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PixelJunk Eden 2', 'From the mind of Baiyon, creative director and hypnotic soundscape composer, for both the award winning Pixeljunk Eden and Eden Obscura, comes Eden 2, an exploration of life, color and collaboration as Grimps reinvigorate and revitalize the world in a swath of luminescence, painting upon a lush canvas as they play. Return to the spectacular, ever changing gardens of psychedelic sights and sounds as you cultivate new plants and biomes, collect pollen and help seeds sprout new exotic leaves and bloom flowers, all against a dynamic and vibrant backdrop of mellow, multi-hued visuals. Swing and spin from silk threads, in both single and cooperative play as you and a partner pirouette around one another in brush-strokes of light and color in the world on your journey to collect the all important “Spectra,” the source of all life in the world. Features: New Grimps with added perks can be unlocked over time, providing new ways to play and experience these strange new worlds. Use a variety of different “spices” to improve pollen gathering, spend more time cultivating the gardens, as well as alter the world in mind bending ways! Relax to the synergetic beats and rhythms created especially for these kaleidoscopic, wonderful worlds. With a multitude of gardens to choose from and many different variants to each, Eden 2 provides countless hours of continuous play. An expansive and eclectic mix of ambient and sensory candy for your ears.' FROM games WHERE igdb_id = 131872 ON CONFLICT (game_id, language_code) DO NOTHING;
