INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Squad', 'Squad is a large scale combined arms multiplayer first-person shooter emphasizing combat realism through communication, team play, emphasizing strong squad cohesion mechanics as well as larger-scale coordination, tactics, and planning. It features 20 large open maps, vehicle-based combined arms gameplay, and player-constructed bases to create a heart-thumping, visceral gaming experience with split-second decision-making in real-world scale firefights.' FROM games WHERE igdb_id = 9495 ON CONFLICT (game_id, language_code) DO NOTHING;
