INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Wonderful 101: Remastered', 'A team of heroes from around the world must unite to protect the earth from vicious alien invaders! This band of 100 Wonderful Ones works together using their fantastic abilities to create a variety of forms. Whether it be a giant fist or a sharp blade, they''ll use their wits and power to overcome the enemy’s pitfalls and perils! And the final member of this team of courageous heroes - is you.' FROM games WHERE igdb_id = 129240 ON CONFLICT (game_id, language_code) DO NOTHING;
