INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fight-crab', 90231, '2020-07-29', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2e8n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ard4a.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fight Crab', 'Welcome to Crab Fight. A new 3D action game where you take control of a crab, and fight off other giant enemy crabs. In this far-off world, These crabs were granted ultimate strength and intelligence from the generous gods. Using their newfound strength and wit, they armed themselves with human weapons of the finest calibur, and took control of the lands. Immortal beings of unrelenting horror, they cannot be killed with swords or even guns. However, there is only one principle fact that rules these lands; “Those who are flipped onto their shells, shall be cooked into a crab cake, or mouth-watering rangoon.” Yes,yes...Crabs who have embarrassingly been flipped over onto their shells will have no choice but to submit to the pot. You are a crab. Aiming to be the best around, you embark on a world tour to flip as many crabs as possible.' FROM games WHERE igdb_id = 90231 ON CONFLICT (game_id, language_code) DO NOTHING;
