INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last of Us Part II: Ellie Edition', 'Set 5 years after the events of The Last of Us, we see the return of Joel and Ellie. Driven by hatred, Ellie sets out for Seattle to serve justice. However, she begins to wonder what justice really means. The Ellie Edition includes: - Game: The Last of Us Part II - The Last of Us Part II Logo Patch - 7" Vinyl Record featuring Music from the Original Soundtrack - Ellie''s Backpack - SteelBook - 48-Page Art Book - Ellie Statue - Lithograph Art Print and Thank You Letter - Ellie''s bracelet - 6 Pins - Five stickers - PS4 Dynamic Theme - Set of 6 PSN Avatars - Digital Art Book' FROM games WHERE igdb_id = 135986 ON CONFLICT (game_id, language_code) DO NOTHING;
