INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed Valhalla: Ultimate Edition', 'In Assassin''s Creed: Valhalla, become Eivor, a legendary Viking raider on a quest for glory. Explore a dynamic and beautiful open world set against the brutal backdrop of England’s Dark Ages. Raid your enemies, grow your settlement, and build your political power in the quest to earn a place among the gods in Valhalla. Assassin''s Creed: Valhalla - Ultimate Edition includes the game, the Ultimate Pack and the Season Pass.' FROM games WHERE igdb_id = 136132 ON CONFLICT (game_id, language_code) DO NOTHING;
