INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dual Universe', 'Dual Universe is a Continuous Single-Shard sandbox MMORPG taking place in a vast Sci-Fi universe, focusing on emergent gameplay with player-driven in-game economy, politics, trade and warfare. Players can freely modify the voxel-based universe by creating structures, spaceships or giant orbital stations, giving birth to empires and civilizations.' FROM games WHERE igdb_id = 19548 ON CONFLICT (game_id, language_code) DO NOTHING;
