INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Tales from the Galaxy''s Edge', 'Star Wars: Tales from the Galaxy''s Edge gives you the chance to explore the planet of Batuu as you live out your own unforgettable story. You’ll fight alongside classic characters and battle intimidating new villains as you explore parts of the galaxy that have never been seen before.' FROM games WHERE igdb_id = 134957 ON CONFLICT (game_id, language_code) DO NOTHING;
