INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rebel Galaxy Outlaw', 'Rebel Galaxy Outlaw is an open-world space combat adventure game, spread across the nearly 40 systems of the Dodge Sector. Play as a mercenary, a trader, a pirate, or whatever mix of the three you feel fits you best. With an engaging storyline and a full conversation system, you can follow the narrative, or ignore it and forge your own path at any time.' FROM games WHERE igdb_id = 107318 ON CONFLICT (game_id, language_code) DO NOTHING;
