INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yuki Onna', 'Yuki Onna is a PS1 inspired survival horror game. Some children went missing out of the blue. You receive a letter that says, "Come alone or I''ll freeze them to death." Out of desperation, you decide to embark on a daunting rescue mission to an abandoned inn up the piercing cold mountains.' FROM games WHERE igdb_id = 126993 ON CONFLICT (game_id, language_code) DO NOTHING;
