INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cooking Mama: Cookstar', 'Cooking Mama: Cookstar keeps the basic Cooking Mama formula with a few new features. The new vegetarian mode lets players avoid cooking meat-based recipes. Players can also show off their creations in the in-game social media network and build their clout over time. Players can use motion controls while the system is in docked mode, or alternate touchscreen controls while playing handheld.' FROM games WHERE igdb_id = 121516 ON CONFLICT (game_id, language_code) DO NOTHING;
