INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mortal-shell-enhanced-edition', 146160, '2020-08-18', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yhh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar10cy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortal Shell: Enhanced Edition', 'Mortal shell is a ruthless and deep action-RPG that tests your sanity and resilience in a shattered world. As the remains of humanity wither and rot, zealous foes fester in the ruins. They spare no mercy, with survival demanding superior awareness, precision and instincts. Track down hidden sanctums of devout followers and discover your true purpose. Possess Lost warriors the Lost remains of defeated warriors are yours to discover. Awaken these Mortal shells, occupy their bodies and significantly open your understanding to diverse masteries of combat. Face formidable foes your path is guarded by adversaries, devoted to inscrutable gods. Behold creatures both pitiable and grotesque and muster your courage and face them down. Iron sharpens Iron combat is strategic, deliberate, and unforgiving. Commit your sword only when an opportunity opens.' FROM games WHERE igdb_id = 146160 ON CONFLICT (game_id, language_code) DO NOTHING;
