INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Total Tank Simulator', 'Total Tank Simulator is a physics-based WW2 game. Experience WW2 like never before. Play with tanks, planes, cannons, infantry and much more. Deploy your units before the battle and issue orders. Watch the battle or take control over every unit on the battlefield. Play one of six historical nations in a huge single player campaign or enjoy battles in multiplayer. Be strategic and remember what Eisenhower said: "In preparing for battle I have always found that plans are useless, but planning is indispensable".' FROM games WHERE igdb_id = 75252 ON CONFLICT (game_id, language_code) DO NOTHING;
