INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dungeon-defenders-awakened', 116021, '2020-05-28', 74, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2q0g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9l8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Defenders: Awakened', 'Defend the most dangerous and gorgeous (we say darngeous) dungeons as four plucky heroes with this unique combo of tower-defense gameplay, ability-based action RPG combat, ever-lasting endgame loot, couch co-op, and online multiplayer. Experience the front-lines of tower defense with friends and fellow defenders — fighting off ferocious hordes in a stunning 3D fantasy world. Four unique heroes, a satisfying RPG leveling system, and an ever-addictive endgame with procedurally generated loot — DD:A celebrates the creativity and collaboration that can only come from four friends trapped in a dungeon against endless waves of orcs with dynamite.' FROM games WHERE igdb_id = 116021 ON CONFLICT (game_id, language_code) DO NOTHING;
