INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hyperparasite', 101257, '2020-04-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20bs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar732.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HyperParasite', 'A rogue-lite twin-stick shooter/brawler that never plays the same twice. Collect and control 60 different characters as the body-snatching alien Parasite with a grudge against humanity. Fight to the top of the food chain: possess the President, push the Big Red Button, and one-up the human race. It''s the 80''s all over again. Only this time, the human race has more than an obnoxious pop culture to contend with. With World War III nearing its demise, Earth only just begins to catch its breath when it is threatened by yet another menace. Unlike the preposterous mullets of its inhabitants, however, this one''s invisible – a parasitic organism capable of making hosts of unsuspecting human beings, consuming what''s left of their souls and wreaking unfathomable havoc. And it''s spreading. With a vengeance. Martial laws have been declared to make way for a global hunt, battle-hardened law enforcers have made allies of the most degenerate of criminals, while the rest of the world is paralyzed with paranoia; yet who can be trusted? Who can see it, let alone destroy it? That''s for them to worry about. For you are the enemy. You are the organism with a mission. You are... HyperParasite.' FROM games WHERE igdb_id = 101257 ON CONFLICT (game_id, language_code) DO NOTHING;
