INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penguin Piste', 'Get your penguin to the bottom of the mountain, avoiding obstacles and collect as many coins as you can to buy all the unlockable extras!  A fast skiing action platformer with genuinely challenging levels.  - Simple controls  - Avoid every obstacle  - Collect as many coins as you can  - Earn all the unlockable extras  Ski, board and snowbike your way down the mountain  Test your skills and timing to reach the high score on every level  All extra content is fully unlockable by completing levels and collecting in game coins! Or coins can be purchased using in-app purchases  https://captainisolation.games/penguin-piste/' FROM games WHERE igdb_id = 134950 ON CONFLICT (game_id, language_code) DO NOTHING;
