INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swords ''n Magic and Stuff', 'Swords ‘n Magic and Stuff is a casual, co-op rpg about, you guessed it, swords, magic and other stuff. Adventure with your friends in a cute but perilous world full of action and adventure. Your role is defined by the items you carry and the way you play. Full online co-op with up to 8 players means that you can play with all your friends! Get lost in the vast world of Tirawyn and become who you want to be.' FROM games WHERE igdb_id = 90235 ON CONFLICT (game_id, language_code) DO NOTHING;
