INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer Dragoon: Remake', 'A new, remade version of the Panzer Dragoon game – true to the original, with improved graphics and controls, that suit modern gaming standards! Pilot through seven unbelievably realistic levels ranging from tropical blue ocean cities to intricate subterranean ruins. Fight the Prototype Dragon who appears together with evil giant dragonflies, frightening man-sized wasps, giant sandworms, and lethal flying battleships. Attack approaching from all sides enemies quickly and without mercy, with improved 360-degree controls and lock-on targeting.' FROM games WHERE igdb_id = 113350 ON CONFLICT (game_id, language_code) DO NOTHING;
