INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dashing Mariachis', 'Dashing Mariachis is a Mexican culture inspired game, situated in early 20th century and heavily relying in Mariachi music with a subtle 8bit treatment, puts the player inside a 3D side-scrolling runner adventure with a gameplay shift at the ending of every stage where now the player has to hit musical notes accordingly in order to keep the Serenata (musical performance) running.' FROM games WHERE igdb_id = 199419 ON CONFLICT (game_id, language_code) DO NOTHING;
