INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sorrowvirus: A Faceless Short Story', 'Faceless: The Sorrowvirus contains an original OST by David Denyer, with accompanying sound design by John Pata. Each instance of gameplay will result in different dialogues to help you find the true ending, as well as discover more of the story behind Faceless. Elements have been extracted from the main game, giving you an idea as to the scenery of the partially derelict Wakeland City that will be seen in Faceless.' FROM games WHERE igdb_id = 115716 ON CONFLICT (game_id, language_code) DO NOTHING;
