INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost of Tsushima: Digital Deluxe Edition', 'The Ghost of Tsushima Digital Deluxe Edition includes the following content: • Game • 1 Technique Point • Charm of Hachiman’s Favor • Hero of Tsushima Skin Set*: Golden Mask, Body Armor, Sword Kit, Horse, Saddle • Digital Mini Art Book by Dark Horse • Director’s Commentary: The creative team sits down with a renowned Japanese historian to look at the world of Ghost of Tsushima and how it compares to the real-life events that inspired it • Ghost of Tsushima Samurai Theme' FROM games WHERE igdb_id = 132978 ON CONFLICT (game_id, language_code) DO NOTHING;
