INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Democratic Socialism Simulator', 'The Democratic Socialism Simulator lets you play as the first socialist president of the United States. Can you redistribute power and wealth while addressing the climate crisis? Enact radical reforms, tax the rich, transform the economy, tackle the most pressing issues without alienating voters or bankrupting the government. But beware: the ruling class won''t give up its power easily. Even your closest allies may turn on you.' FROM games WHERE igdb_id = 131780 ON CONFLICT (game_id, language_code) DO NOTHING;
