INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nira', 'Nira is a fast-paced survival exploration game. Explore endless procedurally generated worlds to gather resources you need to survive. But when night falls, creatures arise. Build a base, craft weapons and tame wild animals to fight hordes of goblins. Explore, Build, Fight, Survive, and find Nira.' FROM games WHERE igdb_id = 126207 ON CONFLICT (game_id, language_code) DO NOTHING;
