INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kidnapped Girl', 'The main character, named Clive, considers himself a psychopath. He has long wanted to hurt someone. So Clive kidnapped a girl on his seventeenth birthday. But the victim was more complicated than he''d thought.' FROM games WHERE igdb_id = 144969 ON CONFLICT (game_id, language_code) DO NOTHING;
