INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('smart-city-plan', 122273, '2020-03-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qat.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arf7k.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smart City Plan', 'Smart City Plan is a modern city builder game: Plan zones, roads, public transport like trains, trams, buses, subways and even the hypertube. Set taxes and policies and implement smart city technologies. Generate a sustainable city and take care of your citizens. Start by creating a few roads and specify zones where your citizens can start building their homes, shops and companies. Once everything runs fine, your can start expanding your city. Extend it by providing public transport for your citizens and implement policies. Ensure everything is taken care for: Pollution, noise, crime, waste, water, energy and so on. Your assistant will help you by guiding your through the process of doing all this easily. The game is running in real-time, but can be accelerated and paused at any time. Manage policies, track financial data, analyze problems in your city. Expand the city when you have figured out how everything works and manage the public transport system, and build new infrastructure buildings, stations, rails, hypertube tracks, bridges, or even space ports.' FROM games WHERE igdb_id = 122273 ON CONFLICT (game_id, language_code) DO NOTHING;
