INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Bros. 35', 'Super Mario Bros. with a 35-player twist Race against time, defeat enemies, and sabotage your opponents in an online* battle to be the last Mario standing! Classic Super Mario Bros. gameplay gets an adrenaline boost! Each player is given the same timed stage, but you must defeat enemies to earn extra time and attack your opponents. Don’t forget to pick up some coins on your way—they can be used to get in-game items like power-ups. With speed, skill, and strategy, you could be the last Mario standing.' FROM games WHERE igdb_id = 138235 ON CONFLICT (game_id, language_code) DO NOTHING;
