INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kaleidoscope-of-phantasm-prison-limited-edition', 121611, '2020-12-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wb5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6hh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaleidoscope of Phantasm Prison: Limited Edition', 'The Limited Edition of the game currently has 4 bonus items. Phantasm Object, an official setting document collection - Includes comments on character design and the heroine''s expressions, comments from the cast, staff members and Ryukishi07. Also includes the Drama CD script. Voice Drama CD, "Closed Room Desk Quiz Tournament" - An alternate story using the same setting as the main game written by Ryukishi07 that reveals a new aspect of the heroine. Cards of fate, 4 piece card set - A reproduction of the Fate Cards from the game. Acrylic art panel, "Hydrangea after the rain - Fuka" - Visual of “Fuka” and “Ku-chan” surrounded by hydrangea shining with dew made into high quality art panels.' FROM games WHERE igdb_id = 121611 ON CONFLICT (game_id, language_code) DO NOTHING;
