INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Splice', 'Pokémon Splice is a Pokémon fan game. It is not a ROM hack, but rather a game for PC made in RPG Maker XP, using Pokemon Essentials. Play as a research assistant, helping Professor Cypress discover new Pokémon forms! Your starter "Arenay" is a special Pokémon that can change to any type! Experience a branching story, with two opposing research organizations you can join! There are multiple chapters with crossing paths!' FROM games WHERE igdb_id = 146982 ON CONFLICT (game_id, language_code) DO NOTHING;
