INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Containment', 'Taking On-Rails Shooters Off Rails Dead Containment is an on-rails shooter inspired by classic arcade light gun games. Players fend off the undead as they race through a city under siege, blasting away the horrors that roam the streets. Play solo or with a friend over online play, collect hidden pickups to boost your score, show off your skills in the stats screen and prove to your friends why you would survive a zombie outbreak. Features: - Solo and Online Co-op - Light gun support - Boss fights - Multiple paths - Rankings - A classic arcade experience - 1 credit mode' FROM games WHERE igdb_id = 133061 ON CONFLICT (game_id, language_code) DO NOTHING;
