INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NHL 21', 'In NHL 21 it’s the most creative, inventive and fearless players that are worth celebrating. Carve your path to superstardom in an expanded "Be A Pro" mode and go down as one of the league’s greatest. On the ice, change up your attack with all new moves, dekes, dangles and evasive maneuvers, inspired by the league’s most groundbreaking innovators. Recognize creativity, recognize revolutionary, recognize future. Recognize greatness.' FROM games WHERE igdb_id = 138538 ON CONFLICT (game_id, language_code) DO NOTHING;
