INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('galaxy-in-turmoil', 19436, '2020-05-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u4w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arja7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxy in Turmoil', 'In Galaxy in Turmoil, players take on the role of Roka, one of the galaxy’s most notorious mercenaries for hire, while she battles through the galaxy on a mission that will either save or destroy her universe. In multiplayer, players will assume the role of a soldier in one of three factions and battle for control in massive 64 player battles featuring full ground to space. Galaxy in Turmoil was originally being developed as a spiritual successor to Star Wars: Battlefront II, to be named Star Wars: Galaxy in Turmoil. It was however shut down by Lucasfilm, and the developers; Frontwire Studios took everything they had currently developed to make a different, though similar game, that features 64-player battles, ground-to-space combat, a single player mode, and removed the Star Wars name from the game.' FROM games WHERE igdb_id = 19436 ON CONFLICT (game_id, language_code) DO NOTHING;
