INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Before I Forget', 'Explore the present to uncover the past, in a short story of love and loss and a life well-lived. A narrative exploration that examines a world where memories are constantly fading and jumbled. A game about dementia and what happens when you can''t hold onto the things you''ve done or the people you''ve loved.' FROM games WHERE igdb_id = 122372 ON CONFLICT (game_id, language_code) DO NOTHING;
