INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Wizard and The Slug', 'When a fugitive wizard meets a forest slug, a strange friendship is born. Together they traverse an oddball fantasy world, unraveling the mystery surrounding an ancient curse. Play as the fastest, most agile slug in video game history together with your spellcasting wizard companion. It''s a team-up you never knew you wanted. Strong focus on humor, character interactions and story.' FROM games WHERE igdb_id = 139400 ON CONFLICT (game_id, language_code) DO NOTHING;
