INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Freedom', 'Sonic Freedom is a 2D hand drawn platformer developed by tripplejaz and marmitoTH in Unity. The sonic fan game wants to bring Sonic into the modern era of platformers with a faithful recreation of momentum based gameplay, drawing on mechanical and level design inspiration from recent metroidvania titles like “Hollow Knight” and “Ori and the Blind Forest,” coupled with an aesthetic grounded in 90s anime as seen in the Sonic CD Toei animations and the “Sonic the Hedgehog” OVA.' FROM games WHERE igdb_id = 130020 ON CONFLICT (game_id, language_code) DO NOTHING;
