INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Röki', 'Rediscover magic and chart your adventure through this forgotten northern world of mystery and monsters. Find your courage, discover hidden paths, solve ancient puzzles and travel deeper through the icy land to learn the truth. We join Tove on a fantastical journey to save her family. A journey that takes her deep into a hidden and long forgotten world of lost folklore filled with strange locations and even stranger creatures. Explore the ancient wilderness, solve its mysteries, save your family in this modern adventure game for all.' FROM games WHERE igdb_id = 28528 ON CONFLICT (game_id, language_code) DO NOTHING;
