INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('country-road-vr', 129835, '2020-03-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2m6u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arnra.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Country Road VR', 'Country Road VR is a virtual petting farm which allows the user to wander the farm and pet many types of animals including a horse, cows, sheep, goats, and a few funny surprises. The animals respond with movement and their corresponding animal sound as the controllers vibrate. In addition, you can walk into a sunflower field and atop a hill overlooking the entire farm. Also, there are butterflies all over, some which land in the palm of your hand! Current updates are underway which will make it even more interactive including the ability to feed the animals. This VR experience is currently on Steam for only $2.99 at https://store.steampowered.com/app/1188140/Country_Road_VR/ and available at VR Junkies (VR Arcades) at locations throughout the US. 20% of the net proceeds goes to Alzheimer''s research. Country Road VR is suitable for ALL ages.' FROM games WHERE igdb_id = 129835 ON CONFLICT (game_id, language_code) DO NOTHING;
