INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infini', 'Integrating an outlandish narrative with rigorous mind-bending puzzles, Infini walks a fine line of meditative and chaotic. Standout visuals and concepts are used to create an imaginative and surrealist world where concepts like Poetry, War, Time, and Hope are personified. After being catapulted into Infinity by War, Hope must find his way back to the real world before it begins to suffer from his absence.' FROM games WHERE igdb_id = 122650 ON CONFLICT (game_id, language_code) DO NOTHING;
