INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Okunoka Madness', 'OkunoKA Madness is a platform game in which you play as KA, a blue-coloured hero who must save the world of souls from the evil hands of Os, his deadly enemy. You will have to jump, run and overcome obstacles through unique and colourful worlds with more than 100 levels, go head-to-head with wacky bosses, find hidden secrets, lots of surprises to unlock and an even more difficult world: Madness!' FROM games WHERE igdb_id = 136462 ON CONFLICT (game_id, language_code) DO NOTHING;
