INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-last-sky', 127157, '2020-06-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co292h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aro1h.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Sky', 'The Last Sky is a narrative puzzle adventure about life, loss, and love. Through its meditative, dreamlike atmosphere you are invited to embark on a journey into Jake''s mind, contemplating the opposites of life & death, fear & love, and loss & hope. A visual odyssey about the beauty and sorrow of life, explore Jake''s past, present, and future, as you progress through the mysterious multi-branching storyline. Enter a surreal dream world, where to overcome the past, Jake must reconnect with the present and the choices that you make will lead to one of several uniquely crafted endings. The Last Sky combines 3D puzzles with 2D platforming inside a beautifully visualized world where the boundaries between dreams and reality dissolve as you become Jake''s rudder in an uncharted ocean.' FROM games WHERE igdb_id = 127157 ON CONFLICT (game_id, language_code) DO NOTHING;
