INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dreadstar-the-quest-for-revenge--1', 140014, '2020-10-20', 45, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2iuf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1x97.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DreadStar: The Quest for Revenge', 'A retro mix of a shoot ''em up gameplay with RPG elements, DreadStar: The Quest for Revenge is inspired by the likes of Tyrian, Raiden and Donpachi. Fast-paced with a primary focus on gunplay rather than bullet hell, DreadStar gives you incremental ways of not only pushing through content, but also improving your ship and its loadout (such as experience, leveling and skill points). If you’re struggling with a sector, you can warp over to Redbeard’s Burrow to spend credits, upgrade your ship and return to where you failed. From Gauss Cannons to Lazer Beams, Hadron Exploders to weapon cooling - ship improvements are key to not only choosing your playstyle but progressing through harder difficulties. With its 4:3 display and CRT mode, to its multiple difficulty settings that offer replayability across its 6 sectors, DreadStar provides an authentic retro experience.' FROM games WHERE igdb_id = 140014 ON CONFLICT (game_id, language_code) DO NOTHING;
