INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wide-ocean-big-jacket', 127591, '2020-02-04', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2uy1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9ap.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wide Ocean Big Jacket', 'An aunt and uncle take their middle-school niece and her boyfriend on an overnight camping trip. Roast hot dogs on the fire, go birdwatching, tell ghost stories, grab a beverage from the cooler and do cartwheels on the beach. Wide Ocean Big Jacket is a short story game including 20 chapters, four playable characters, 10,000 words of dialog and 8 explorable areas, all rendered in a beautiful 2D/3D art style.' FROM games WHERE igdb_id = 127591 ON CONFLICT (game_id, language_code) DO NOTHING;
