INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dwarrows', 'A peaceful 3rd person adventure and town-building game. Explore, gather, build, befriend, and quest in a beautifully handcrafted world. Build and grow a new settlement and explore the lands surrounding it in this Peaceful Action-Adventure & Town-Builder. Search the lush forests of the Dusken Woodlands for resources, and adventure through mysterious new places to find lost artifacts. Meet strange and quirky characters along the way, invite wandering people to join your town, and befriend cute animals who may help you in your travels. Control your team of three uniquely skilled characters to gather resources, build structures, and find treasure.' FROM games WHERE igdb_id = 25229 ON CONFLICT (game_id, language_code) DO NOTHING;
