INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Tale of Crowns', 'A Tale of Crowns is a high fantasy romance with Middle Eastern roots. It’s entirely text-based, with choices throughout to shape both your main character’s personality and skills as well as influence their relationships with others. There are four love interests for you to choose from, both female as well as male, each with their own stories and secrets for you to uncover!' FROM games WHERE igdb_id = 178751 ON CONFLICT (game_id, language_code) DO NOTHING;
