INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alpaca Ball: Allstars', 'Alpaca Ball: Allstars is a physics based football game featuring alpacas as players. Instead of using their feet to play the ball, these alpacas play the ball with their heads and oversized necks. The game features local multiplayer for up to 8 players, and a solo or co-op career mode with a light story in which you travel the world to become the best alpaca ball player to save your home.' FROM games WHERE igdb_id = 139133 ON CONFLICT (game_id, language_code) DO NOTHING;
