INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('acies-battle-runes--1', 142594, '2020-09-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4gux.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar12m7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Acies: Battle Runes', 'Acies: Battle Runes is a strategy card game that you can play with your friends. Build your deck with over 50 cards to suit your characteristics and add the special abilities that you like. Battle with users in real time from 1vs1 to 3vs3 and summon up to 1200 units to battle! Grow your units and awaken the sleeping power of the hero using over 130 types of runes. Become a great strategist as you take the throne in Acies: Battle Runes!' FROM games WHERE igdb_id = 142594 ON CONFLICT (game_id, language_code) DO NOTHING;
