INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cross the Moon', 'Something once great lies dormant beneath the cold streets of Armorica''s isolated capital, L''Amour. When it sleeps it dreams, and when it dreams it hunts. Fates converge as a young man''s mysterious death brings sibling vampires Aurore and Lux Amanite into a world of occult obsession and corporate corruption. Meanwhile, police inspector Ryouko Otsuki arrives in L''Amour to find a city whose identity is just as severed and broken as her own…' FROM games WHERE igdb_id = 152151 ON CONFLICT (game_id, language_code) DO NOTHING;
