INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Get-A-Grip Chip', 'Get-A-Grip Chip is a charming and satisfyingly challenging grappling hook 2D platformer. Master the hook and fling through the increasingly intense floors of Roboco Mfg. Chuck Chip over chainsaws, launch over lasers, and even escape chases with Scan-It Janet.' FROM games WHERE igdb_id = 132314 ON CONFLICT (game_id, language_code) DO NOTHING;
