INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel''s Spider-Man Remastered', 'Included in the Ultimate Edition of Marvel''s Spider-Man: Miles Morales, this is a Playstation 5 remaster of Marvel''s Spider-Man and all of its DLC. The remastered version features improved skin, eyes, hair, and facial animation, as well as ray-traced reflections, ambient shadows, and improved lighting. More pedestrians and vehicles are also seen in the remaster. Marvel''s Spider-Man: Remastered also adds three new Spider-Man suits which were not in the original game, as well as new photo mode features and new trophies.' FROM games WHERE igdb_id = 138949 ON CONFLICT (game_id, language_code) DO NOTHING;
