INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('phonequest', 134694, '2020-06-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29mo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8blu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phonequest', 'Phonequest is a game about making friends online.  You''re Sam and you''re wasting time on the Internet, home alone. Suddenly, you receive a strange prank call, and a minute later you''ve already got yourself in a pretty big turmoil, involving aliens invading Earth. Get your negotiation skills ready and prepare for a wild intergalactic ride.  Phonequest takes inspiration from Homestuck and super old point & click adventure games I found on CD disk when I was cleaning my basement room. People also found it similar to Emily''s Away and Undertale, but I don''t know if they are right as I''ve not played these games thoroughly. Play Phonequest yourself and then tell me!' FROM games WHERE igdb_id = 134694 ON CONFLICT (game_id, language_code) DO NOTHING;
