INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'There Is No Game: Wrong Dimension', '"There is no game: Wrong dimension" is a Point&Click comedy adventure (and Point&Click only!) that will take you on a journey you never asked to go on, through silly and unexpected video game universes. Will you be able to play along with the "Game" to find your way home? We sincerely think NOT.' FROM games WHERE igdb_id = 132907 ON CONFLICT (game_id, language_code) DO NOTHING;
