INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Good Job!', 'As the clumsy child of a CEO, you must climb the corporate ladder one office-themed puzzle at a time! Complete puzzles in multiple ways as you experiment with the interactive environments—a projector can be wheeled gently through an electric door…or catapulted through the wall. So toil (or tumble) your way to the top and make your father proud!' FROM games WHERE igdb_id = 131962 ON CONFLICT (game_id, language_code) DO NOTHING;
