INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disc Space', 'Disc Space is a multiplayer Ultimate Frisbee game with up to 10 players online. Play with your friends or find new ones. Unlimited fun is guaranteed.  Features:  - Play 3v3, 4v4, 5v5 Ultimate Frisbee game  - Play with your friends or against ''Computer AI''  - Select specialization to match your play style: Handler, Cutter, Cannon, Newbie or D-Machine' FROM games WHERE igdb_id = 141087 ON CONFLICT (game_id, language_code) DO NOTHING;
