INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Townscaper', 'Townscaper is an experimental passion project. More of a toy than a game. Pick colors from the palette, plop down colored blocks of house on the irregular grid, and watch Townscaper''s underlying algorithm automatically turn those blocks into cute little houses, arches, stairways, bridges and lush backyards, depending on their configuration.' FROM games WHERE igdb_id = 135789 ON CONFLICT (game_id, language_code) DO NOTHING;
