INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Human Simulator', 'Meet Mr Hugh Mann. Hugh loves humans, and he wants to be just like them. Help Hugh to fit in and learn what human life is like by manually moving his head, arms and legs as you work together to explore an array of fun and wacky jobs in the pursuit of helping Hugh to fit and be accepted by all!' FROM games WHERE igdb_id = 128246 ON CONFLICT (game_id, language_code) DO NOTHING;
