INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('before-we-leave', 120878, '2020-05-08', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7k34.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/areo2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Before We Leave', 'Before We Leave is a non-violent city building game set on multiple planets in your own cozy corner of the universe. Your people emerge from a long period hidden underground and they’ve forgotten the world above. Rebuild civilization back to what it once was by building huts, harvesting potatoes and expanding your reborn society to other continents and eventually other planets. Manage resources, discover ancient tech and create a multi-planet network of colonies to thrive in your solar system. But the universe is not always a safe place. Ancient guardians, remnants of your ancestors, will demand your attention and challenge your cities. The planets you inhabit are scarred by the disasters that forced your forebears underground, and those disasters will still plague you if not managed properly. And most of all, watch out for vast planet-eating space whales coming to graze on your planets! Before We Leave is a (mostly) non-violent game. There are no weapons, no fighting your neighbours for control of resources and unless you fail to handle an incoming space whale, your people will not die. Play, expand and chill out at your own pace in your own solar system of rehabilitated planets!' FROM games WHERE igdb_id = 120878 ON CONFLICT (game_id, language_code) DO NOTHING;
