INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kirby-fighters-2', 139059, '2020-09-23', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xex.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcd8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby Fighters 2', 'Choose from a cast of Kirby''s most iconic copy abilities - including the brand new Wrestler ability - and duke it out to be the last Kirby standing. Familiar friends and foes like Bandana Waddle Dee and King Dedede also make an appearance as playable characters. Prove your pink puffball prowess and scale the tower in Story Mode! Meta Knight and King Dedede have seemingly teamed up to challenge Kirby to a buddy gauntlet! Fight alongside a buddy (player or computer controlled) to scale the tower, choosing helpful items between each round that will power you up for the rest of your ascent. Each of the playable abilities and characters has a distinct play style and set of moves. Abilities like Cutter and Archer excel at ranged attacks, while Wrestler and Fighter like to get up close and personal! Other characters like Gooey and Bandana Waddle Dee bring a variety of moves from past Kirby games. Experiment with them all to find and master your favorite.' FROM games WHERE igdb_id = 139059 ON CONFLICT (game_id, language_code) DO NOTHING;
