INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BPM: Bullets Per Minute', 'In BPM, all of your actions and the actions of your enemies are tied to the beat of the music. Your enemies perform a dance-like sequence of attacks to an epic rock opera. BPM is inspired by retro shooters of the 90’s. It is fast, frenetic and rhythmical. You can double jump, dash, rocket jump and bunny hop to evade your opponents.' FROM games WHERE igdb_id = 133330 ON CONFLICT (game_id, language_code) DO NOTHING;
