INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirt 5', 'Dirt 5 is the bold new off-road racing experience created by Codemasters. Blaze a trail across the most iconic routes in the world. Drive the widest roster of cars from rally icons, to trucks, to GT heroes and lots more. Play through a star-studded Career, four-player split-screen, innovative online modes, livery editor and more new features, DIRT 5 is the next generation of extreme racing.' FROM games WHERE igdb_id = 133301 ON CONFLICT (game_id, language_code) DO NOTHING;
