INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mars Horizon', 'In Mars Horizon the player is tasked with leading a major space agency from the dawn of the space age though to humanity''s journey to Mars. Players run a government space agency from when the first rockets launched into the atmosphere, right through to the first crewed mission to Mars. Research new tech, expand your agency base, build rockets, send satellites into orbit, and launch a variety of missions. As the player, you’re in charge of every element of the journey into space.' FROM games WHERE igdb_id = 101183 ON CONFLICT (game_id, language_code) DO NOTHING;
