INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sludge Life', 'Sludge Life is a first-person open world vandalism-centric stroll through a polluted island full of cranky idiots and a vibe so thick you can taste it. Roam a tiny island stuck on a sludge covered planet as upcoming tagger GHOST, a breezy bandit set on staking their claim amongst the graffiti elite. Traverse the corporately branded landscape, link up with other taggers, and steal junk and hearts along the way. Will you become the king of the island and tag every open inch, infiltrate sludge-pumping corporation GLUG, or just take it all down in flames with you?' FROM games WHERE igdb_id = 131705 ON CONFLICT (game_id, language_code) DO NOTHING;
