INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phoenotopia: Awakening', 'Join Gail, a simple villager, who must heed the call for adventure when a great starship appears in the night sky and abducts all the adults. As the new oldest member of her fragmented community, she must set out to solve this great mystery. Little does she know of the grand adventure before her, the evil lurking in the shadows, and the role she will play in the fight for Earth’s very existence!' FROM games WHERE igdb_id = 136805 ON CONFLICT (game_id, language_code) DO NOTHING;
