INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('swimsanity', 63572, '2020-08-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2j3e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6qy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swimsanity!', 'Swimsanity! is a multiplayer underwater shooter with action-packed Co-Op and Versus game modes, all supported by online and local play. You play as our hero Mooba, who uses a variety of unique power ups and weapons to survive in this aquatic world. Whether you''re teaming up with friends to swim into Adventure mode, or clashing in competitive matches such as Last Mooba Standing, there''s more than 150+ challenges to complete across 8 action-packed Game Modes in Swimsanity! All modes can be played online or locally. 4 PLAYER ONLINE CO-OP! Team up to unlock content and complete challenges with players around the world. 4 PLAYER ONLINE VERSUS! Join casual or ranked matches to compete and climb the Leaderboards to be crowned the best in the world. LOCAL CO-OP AND VERSUS! Feel the intensity in the room with some couch play with up to four friends. If anyone''s missing, play with bots fill their spot. ONLINE CROSS-PLAY! Play with anyone online across the Xbox One, PC and Consoles! UNLEASH SWIMSANITY! Unlock 10+ eye-popping Unleashes to bring to battle for devastating moves. COMPLETE 150+ CHALLENGES! There''s always more to do by completing over 150 challenges across 8 Game Modes.' FROM games WHERE igdb_id = 63572 ON CONFLICT (game_id, language_code) DO NOTHING;
