INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Granblue Fantasy: Versus', 'Embark on a new fight, O champions of the skies! Take a ringside seat for this brawltastic work! An exciting new title in the Granblue Fantasy series is finally revealed! Featuring stunning visuals, heart-pounding music, and innovative game mechanics, it’ll usher in a new era of fighting games! This fantasy game blends fighting game action and RPG-style adventure. Throw yourself into matches or enjoy powering up your characters!' FROM games WHERE igdb_id = 113378 ON CONFLICT (game_id, language_code) DO NOTHING;
