INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anno 1404: History Edition', 'Relive the captivating gameplay of a true city-building classic with Dawn of Discovery and its Venice expansion in Anno 1404 History Edition. See the game like never before, updated and optimized to work smoothly on current computers with resolutions of up to 4K, and enjoy all improvements while continuing your existing game with full save compatibility.' FROM games WHERE igdb_id = 135738 ON CONFLICT (game_id, language_code) DO NOTHING;
