INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ary-and-the-secret-of-seasons', 54645, '2020-08-31', 54, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xlb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar99z.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ary and the Secret of Seasons', '"Ary and the secret of seasons is an adventure game introducing the possibility to navigate between all the seasons. In this epic story, you will follow the journey of Ary across the world of Valdi. This young girl will join the guardians of seasons, an old organization traditionally ruled by men. As a new season’s guardian, her self-control and courage will lead her where no other guardian has been, and she will successfully restore the seasons in Valdi."' FROM games WHERE igdb_id = 54645 ON CONFLICT (game_id, language_code) DO NOTHING;
