INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rock of Ages 3: Make & Break', 'Rock of Ages 3: Make & Break is competitive tower defense and arcade action rolled up with ACE Team''s quirky, Monty Python-esque humor into one giant, creative game for the ages. Jump into the expansive, gut-busting story for an eclectic adventure featuring bizarre and irreverent takes on legendary characters, or for the first time, create and share your own levels to compete with friends and strangers online in a real-time mix of hectic tower defense and epic boulder-racing arcade action.' FROM games WHERE igdb_id = 121714 ON CONFLICT (game_id, language_code) DO NOTHING;
