INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('samurai-jack-battle-through-time', 131687, '2020-08-21', 67, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co206e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbdb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Jack: Battle Through Time', 'Become Samurai Jack, the greatest warrior across time. Journey through time to finally stop Aku’s evil reign in this new adventure told by the creators of Samurai Jack. Voiced by the original voice-actors, Samurai Jack: Battle Through Time is an action platform game that spans across time and space, where your actions will determine a new legend! An Untold Adventure That Ties Into the Epic Series Finale - Team up with trusted allies from the show to face off against familiar enemies. Explore Worlds from the Award Winning Series - Visit classic worlds and moments from your favorite episodes. Travel to a dark future to free mankind. Dive into the past to face off against diabolical monsters. Seek your fate as you travel across space and time. Create Your Own Legend - Equip and master over a dozen different weapons in combat. Increase your power even more by training and unlocking new skills to support your playstyle.' FROM games WHERE igdb_id = 131687 ON CONFLICT (game_id, language_code) DO NOTHING;
