INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Necronator: Dead Wrong', 'Necronator: Dead Wrong is a comedic micro RTS game with a deck-building twist. Collect and deploy undead units and build an army to conquer the insufferable goody-two-shoes of the Livmor Alliance. Raise the dead, drop the mic. Those instructors at the Undead Academy don''t understand your talent. Why trudge your way through years of training... when you could just make a deal with an evil ancient demi-god? Choose a unique commander and join forces with the all-powerful Necronator to conquer the Livmore Alliance and restore the Necronator to his former glory.' FROM games WHERE igdb_id = 122064 ON CONFLICT (game_id, language_code) DO NOTHING;
