INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yakuza: Like a Dragon', 'Yakuza: Like a Dragon is a role-playing game developed and published by Sega. Released in 2020, it is the eighth main entry in the Yakuza series. The game introduces a new protagonist, Ichiban Kasuga, and departs from the traditional action combat system, instead featuring turn-based combat with a party of characters. Set in the fictional city of Yokohama, the game follows Kasuga''s quest for revenge and his journey through Japan''s criminal underworld.' FROM games WHERE igdb_id = 36550 ON CONFLICT (game_id, language_code) DO NOTHING;
