INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bleeding Edge', 'From the studio behind DmC: Devil May Cry and Hellblade: Senua’s Sacrifice comes Bleeding Edge, a fast and frenetic 4v4 team brawler where every fighter comes mechanically enhanced for mayhem! Choose your fighter and join a team of super-charged renegades from the edges of society: burn rubber as bold and beautiful Buttercup with her detachable buzzsaw arms, tear it up as Black Metal rocker Nidhoggr with his electrifying guitar solos, or slash up the streets as New York’s most wanted ninja, Daemon.' FROM games WHERE igdb_id = 119260 ON CONFLICT (game_id, language_code) DO NOTHING;
