INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Gangs', 'Shadow Gangs is an arcade style ninja action game. The graphics are HD hand drawn and traditional style animated. The soundtrack was made by a lead guitarist over a 5 years period. You play the role of Dan the current ninja order master. Your mission is to rescue your family from the Shadow Force crime organisation, whose members are known as the Shadow Gangs. Use your ninja transformation ability and your special powers.' FROM games WHERE igdb_id = 133056 ON CONFLICT (game_id, language_code) DO NOTHING;
