INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('into-a-dream', 129629, '2020-07-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21vm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardfk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Into a Dream', 'In Into A Dream you wake up in a mysterious place devoid of all your memories and come upon a recording addressed to you. As you listen to it, you realize that your mind has been linked to the dreams of a Luke Williams, a man diagnosed with severe depression. You are Luke''s last hope and must prevent him from… fading away. Delving deep into Luke''s dreams, where memories and symbols are blended together, you are expected to disclose the events and actions that have led Luke to his darkness. You will meet his close family and friends and must find ways to trick him into letting you access his darker dreams and unveil the emotional, powerful and heartbreaking journey of his life. Luke''s life is in your hands. You have to help him take the first step towards recovery; to make him see that his life matters… You are his last hope. Key Features -A cinematic presentation and unique visual experience -An emotional, heartbreaking and humane narrative about love, hopelessness and depression -Beautiful original soundtrack and dreamlike atmosphere -Puzzle-solving woven into the game''s environment -Full character voice over -A complex story featuring real characters and relationships' FROM games WHERE igdb_id = 129629 ON CONFLICT (game_id, language_code) DO NOTHING;
