INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('paper-beast', 117293, '2020-03-24', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1mu2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5yx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paper Beast', 'From the creative mind of renowned game designer Eric Chahi (Another World, Heart of Darkness, From Dust) comes Paper Beast, a playful exploration game of big data and vibrant wildlife. Paper Beast will see player-explorers discover an ecosystem born out of lost code and forgotten algorithms. They will interact with ever-evolving environments and will form delicate bonds with emotionally stirring creatures. Following an unspoken narrative, players will interact with fascinating wildlife that adapts its behaviour to the player’s actions. Paper Beast is a poetic fusion of VR technology and immersive gameplay experiences, with a deep simulation system at its core.' FROM games WHERE igdb_id = 117293 ON CONFLICT (game_id, language_code) DO NOTHING;
