INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mount & Blade II: Bannerlord', 'Mount & Blade II: Bannerlord is the eagerly awaited sequel to the acclaimed medieval combat simulator and role-playing game Mount & Blade: Warband. Set 200 years before, it expands both the detailed fighting system and the world of Calradia. Bombard mountain fastnesses with siege engines, establish secret criminal empires in the back alleys of cities, or charge into the thick of chaotic battles in your quest for power.' FROM games WHERE igdb_id = 9608 ON CONFLICT (game_id, language_code) DO NOTHING;
