INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Rock Galactic', 'Deep Rock Galactic is a first-person co-operative sci-fi shooter for up to 4 players, featuring fully procedural and destructible environments to explore, mine, and explode your way through to reach your objectives. As a team of veteran dwarven space miners, you must take on perilous missions for the interplanetary mining corporation Deep Rock Galactic and go where no-one else dares, into the deepest, most dangerous cave systems of the most hostile planet ever discovered.' FROM games WHERE igdb_id = 27134 ON CONFLICT (game_id, language_code) DO NOTHING;
