INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mafia II: Definitive Edition', 'Remastered in stunning HD detail, live the life of a gangster during the Golden-era of organized crime. War hero Vito Scaletta becomes entangled with the mob in hopes of paying his father’s debts. Alongside his buddy Joe, Vito works to prove himself, climbing the family ladder with crimes of larger reward, status and consequence. It includes the DLCs released for the original game ("The Betrayal of Jimmy", "Jimmy''s Vendetta", and "Joe''s Adventures").' FROM games WHERE igdb_id = 134071 ON CONFLICT (game_id, language_code) DO NOTHING;
