INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('puyo-puyo-tetris-2', 137132, '2020-12-07', 77, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3246.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar783.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puyo Puyo Tetris 2', 'Stack, chain, and combo your way to victory in the ultimate matching of two puzzle game legends! Pre-order now and get ready to traverse dimensions and experience brand new worlds in time for the holidays, with the PC release fast-dropping onto Steam in early 2021. In Puyo Puyo Tetris 2, players will experience a brand-new hilarious story filled with an eclectic cast of characters in Adventure mode and develop new strategies for play utilizing special item cards in Skill Battle. Read on for more! Boost your strategy and power your team in Puyo Puyo Tetris 2‘s brand-new Skill Battle mode with this pack of eight in-game rare Item Cards–including three special cards featuring items from the Sonic the Hedgehog series! This pack is exclusive to the Puyo Puyo Tetris 2 Launch Edition. More Legendary Battles? YIP-YIP-YIP! Perfectly blending the complementary gameplay of Puyo Puyo, one of Japan’s most enduring and popular game brands, and Tetris, one of the most well-known video game franchises in the world, Puyo Puyo Tetris 2 provides a unique crossover experience with addictive puzzle challenges, loads of content, and overflowing charm for players of all ages. Expanding on the addictive gameplay of its predecessor, Puyo Puyo Tetris 2 is packed with fun, new modes where players can precisely pop Puyos and tactically rotate and clear Tetriminos solo or with friends, offline and online!' FROM games WHERE igdb_id = 137132 ON CONFLICT (game_id, language_code) DO NOTHING;
