INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Immortals Fenyx Rising', 'From the creators of Assassin’s Creed Odyssey comes a storybook adventure about a forgotten hero on a quest to save the Greek gods. Embark on a journey to the Isle of the Blessed, taken over by dangerous creatures of mythology. Prove your legendary heroism by taking on their leader, Typhon, the deadliest monster in all of mythology in a face-off for the ages. Explore a beautiful fantasy world where tricky puzzles, mysterious dungeons and heroic feats await. The journey will be as challenging and rewarding as the final destination. Will you be the Hero of the legends foretold?' FROM games WHERE igdb_id = 119357 ON CONFLICT (game_id, language_code) DO NOTHING;
