INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of the Sea', 'Call of the Sea is a first-person adventure puzzle game set in the 1930''s that tells the story of Norah, a woman on the trail of her missing husband''s expedition. The search takes place on a strange but beautiful island in the South Pacific, filled with secrets waiting to be unearthed. It’s an otherworldly tale of mystery, adventure, and self-discovery.' FROM games WHERE igdb_id = 133306 ON CONFLICT (game_id, language_code) DO NOTHING;
