INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Persona 5 Strikers', 'Persona 5 Strikers is a crossover between Koei Tecmo''s hack and slash Dynasty Warriors series and Atlus''s turn-based role-playing game Persona series. As a result, it features gameplay elements from both, such as the real-time action combat of the former with the turn-based Persona-battling aspect of the latter. The game is set six months after the events of Persona 5, and follows Joker and the rest of the Phantom Thieves of Hearts as they end up in a mysterious version of Tokyo filled with supernatural enemies.' FROM games WHERE igdb_id = 117731 ON CONFLICT (game_id, language_code) DO NOTHING;
