INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('void-terrarium', 122721, '2020-01-23', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rfr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc3w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Void Terrarium', '"Even in the darkest times, hope is homegrown. Void Terrarium chronicles the story of a robot and a young girl in a world devastated by enigmatic events. Explore hauntingly beautiful ruins in search of food and supplies, outfit and maintain the "terrarium" in which you live, and do whatever it takes to protect and nurture the last surviving human in this care simulator-meets-roguelike title." void tRrLM(); //Void Terrarium is a roguelike RPG set in a ruined world contaminated by fungi, starring the last human girl Toriko and a helper robot. Since Toriko is unable to survive in the polluted world, the player takes on the role of the helper robot, who must replenish the environment of the “Terrarium” where she spends each day.' FROM games WHERE igdb_id = 122721 ON CONFLICT (game_id, language_code) DO NOTHING;
