INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA 21: Champions Edition', 'Win as One in EA SPORTSFIFA 21, powered by Frostbite. Whether it''s on the streets or in the stadium, FIFA 21 has more ways to play than ever before - including the UEFA Champions League and CONMEBOL Libertadores. FIFA 21 - Champions Edition includes: - 3 Days Early Access - Up to 12 Rare Gold Packs, 1 per week for 12 weeks - Cover Star Loan Item, for 5 FUT matches - Career Mode Homegrown Talent, local youth prospect with world-class potential - FUT Ambassador Player Pick, choose 1 of 3 player items for 3 FUT matches - Special Edition FUT Kits and Stadium Items' FROM games WHERE igdb_id = 136062 ON CONFLICT (game_id, language_code) DO NOTHING;
