INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultrakill', 'Ultrakill is a fast-paced ultraviolent retro FPS combining the skill-based scoring from character action games with unadulterated carnage inspired by the best shooters of the 90''s. Rip apart your foes with varied destructive weapons and shower in their blood to regain your health.' FROM games WHERE igdb_id = 124333 ON CONFLICT (game_id, language_code) DO NOTHING;
