INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Heroes: Trails into Reverie', 'The Legend of Heroes: Trails into Reverie is the tenth installment in the main Trails series, serving as a direct sequel to the events of the The Legend of Heroes: Trails of Cold Steel IV and the epilogue to both the Crossbell and Erebonia arcs. The game follows the footsteps of the liberator Lloyd Bannings, the war hero Rean Schwarzer, the masked enigma "C" and switch between each of their paths freely with the Crossroads system, three different legends are about to unfold!' FROM games WHERE igdb_id = 136673 ON CONFLICT (game_id, language_code) DO NOTHING;
