INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phasmophobia', 'Phasmophobia is a 4 player online co-op psychological horror where you and your team members of paranormal investigators will enter haunted locations filled with paranormal activity and gather as much evidence of the paranormal as you can. You will use your ghost hunting equipment to search for and record evidence of whatever ghost is haunting the location to sell onto a ghost removal team. You can choose to support your team by monitoring the location with CCTV cameras and motion sensors from the safety of the truck or head inside and get your hands dirty with the ghostly activity that will get increasingly hostile as time goes on.' FROM games WHERE igdb_id = 132516 ON CONFLICT (game_id, language_code) DO NOTHING;
