INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Potion Commotion', 'Live the CRAZY life of a Wizard’s assistant in this hilarious Clicker game! You’ll be in charge of making wacky and wonderful Potions, using ingredients produced in your garden. With plenty of twists and turns along the way, the fun never stops! Do you have what it takes?' FROM games WHERE igdb_id = 130128 ON CONFLICT (game_id, language_code) DO NOTHING;
