INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beautiful-desolation', 56914, '2020-02-26', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1zt4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9vm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beautiful Desolation', 'A post-apocalyptic adventure game set in a world you have never seen before. The Penrose appeared without warning. One day the sky was empty, and the next it was filled by an impossibly shaped monolith. Tragedy hit home for Mark and Don Leslie, when an incident tore apart their brotherly bond in this dramatic story that spans the 1980s and beyond. Allow the Leslie family''s story to unfold as you delve into a unique adventure with BEAUTIFUL DESOLATION, to explore this futuristic wasteland to discover villages, destroyed cities, and uncover the secrets of strange and abandoned technology. The never before seen, African, post-apocalyptic setting opens up a menagerie of bizarre creatures and vibrant characters, alongside a new world inspired by Sub-Saharan flora and fauna. But beware, newcomers are either revered or hated.' FROM games WHERE igdb_id = 56914 ON CONFLICT (game_id, language_code) DO NOTHING;
