INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('birushana-rising-flower-of-genpei', 145094, '2020-09-17', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4b2s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1jii.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Birushana: Rising Flower of Genpei', 'Fifteen years after the Heiji Rebellion, the Heike clan has reached the height of its power, while the Genji clan remains devastated by defeat. Hidden deep within the mountains of Kurama lives Shanao, the youngest surviving male heir to the Genji name. However, Shanao harbors a deep secret known by very few. The youngest heir to the Genji name is no man. Torn between her duty to live up to the Genji family name and her desire to live a peaceful life, Shanao sets off in hopes to take down the Heike stronghold and finally bring peace in the country. Her adventure leads her to find new cherished relationships, as well as something deeper than the feud between the rivaling clans.' FROM games WHERE igdb_id = 145094 ON CONFLICT (game_id, language_code) DO NOTHING;
