INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Way Back Home', 'A post apocalyptic survival horror game in the middle of an outbreak follows the main Protagonist, Tenriyu Amuro. A father went to the manila for a job for his familly after he leaves their province. Only to find himself in the middle of chaos where a virus causes Agression, Hunger And Violence to humans. He must fight his way back home and escaped the quarantined city.' FROM games WHERE igdb_id = 127742 ON CONFLICT (game_id, language_code) DO NOTHING;
