INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('asterix-and-obelix-xxl-romastered', 138352, '2020-10-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2iul.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9b2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asterix & Obelix XXL: Romastered', 'Asterix and Obelix make an XXL comeback in a Romastered version full of Romans! The year is 50 B.C. Gaul is entirely occupied by the Romans. Well, not entirely... One small village of indomitable Gauls still holds out against the invaders. And life is not easy for the Roman legionaries who garrison the fortified camps of Totorum, Aquarium, Laudanum and Compendium. Peace reigns in the small Armorican village, where the villagers go about their daily business. Our two heroes, Asterix and Obelix, hunt wild boar, the blacksmith and the fishmonger quarrel, and the village chief strolls around the village square atop his shield. After a fine day''s hunting, Asterix and Obelix return to find their village in flames, pillaged by the Romans! They set off to rescue their fellow villagers, accompanied by their faithful Dogmatix. Their journey will take them to Normandy, Greece Helvetia, Egypt and, finally, Rome, in order to save the villagers from the clutches of the emperor Caesar...' FROM games WHERE igdb_id = 138352 ON CONFLICT (game_id, language_code) DO NOTHING;
