INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('maid-of-sker', 111544, '2020-07-28', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25mq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar773.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maid of Sker', 'Maid of Sker is a first-person survival horror, set in a remote hotel with a macabre history from Welsh folklore. Brave the nightmares of the Quiet Men. When they arrive, do not panic — don''t even breathe. Featuring realistic 4k visuals with gameplay focused on story, exploration and no-weapon survival tactics. Experience a multiple thread narrative where your decisions matter, unlocking different story paths and multiple endings. A 3D sound based AI system is the core survival gameplay mechanic. Hide, run, creep, trap and distract are some of the techniques you need to master to survive enemies with super hearing. As you progress, enemies become more difficult to avoid, to the point where standing still and holding your breath is the only option! Time it correctly and you’re safe, for now. Run out of breath and — suffer.' FROM games WHERE igdb_id = 111544 ON CONFLICT (game_id, language_code) DO NOTHING;
