INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drawkanoid', 'Smash things at hyperspeed in Drawkanoid, a re-imagining of the classic brick-breaking genre. Draw your paddle to bounce blindly fast balls exactly where you want them. There''s bullet time to help you out, but the game gets faster as you get better. Upgrade your ship and deploy powerups strategically to help you survive and score huge combos in the blink of an eye. Last brick syndrome is dead!' FROM games WHERE igdb_id = 107247 ON CONFLICT (game_id, language_code) DO NOTHING;
