INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Manor', 'Midnight Manor is a short narrative-driven "pick-em-up" platformer inspired by games like Bible Adventures, Super Mario Bros 2, and Lakeview Cabin Collection. It follows the story of a man down on his luck, who happens to find himself at the doorstep of a luxurious manor as a terrible storm surges outside. Greeted by a generous, but lonely, old man - he''s offered shelter in exchange for completing some simple tasks during his stay. So... enter the Midnight Manor. Explore its winding hallways. Fulfill your piece of the bargain, and enjoy a night of luxury sheltered from the churning storm outside.' FROM games WHERE igdb_id = 134721 ON CONFLICT (game_id, language_code) DO NOTHING;
