INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel''s Avengers Definitive Edition', 'Marvel’s Avengers is an action-adventure game developed by Crystal Dynamics and published by Square Enix in 2020. It features both a single-player campaign and multiplayer missions, combining narrative-driven gameplay with cooperative online play. The story follows Kamala Khan as she reunites the Avengers after a catastrophic event. Players can control multiple heroes, each with unique abilities and skill trees. The Definitive Edition includes all released DLC missions and heroes.' FROM games WHERE igdb_id = 259466 ON CONFLICT (game_id, language_code) DO NOTHING;
