INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ensou', 'Ensou is a top-down 2D Action game focused on fighting between samurai in Japan''s Edo Period, with an attack and defense system based on timing and parries. After the fall of the Yamamoto school in the city of Isagawa, Hiroyuki Ishigame is tasked with eliminating Naosuke Wachi, the greatest pupil of the old martial arts master Gensuke. This task will make Ishigame take a new direction in his life: the Path of the Five Rings.' FROM games WHERE igdb_id = 141212 ON CONFLICT (game_id, language_code) DO NOTHING;
