INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night of the Consumers', 'It''s your first day on the job and the store is closing in a matter on minutes. The consumers, with their unrelenting thirst for customer service are still prowling the aisles and there are shelves still to be stocked up. The store needs to be kept in pristine condition, and empty shelves will not be tolerated by The Manager. Welcome to hell.' FROM games WHERE igdb_id = 131859 ON CONFLICT (game_id, language_code) DO NOTHING;
