INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyberpunk 2077', 'Cyberpunk 2077 is an open-world action-adventure game set in Night City, a sprawling metropolis driven by power, glamour, and body modification. Players assume the role of V, a mercenary outlaw in pursuit of a unique implant that holds the key to immortality. The game allows extensive customization of cyberware, skills, and playstyle. Choices made throughout the journey influence both the narrative and the world.' FROM games WHERE igdb_id = 1877 ON CONFLICT (game_id, language_code) DO NOTHING;
