INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inseparable', 'Inseparable is a highly cooperative pc game for two players (on one keyboard), but playing solo is also possible. Placed in a fantasy world with a vintage style. This game is a fusion of adventure and action. It requires very good coordination from the players.' FROM games WHERE igdb_id = 140291 ON CONFLICT (game_id, language_code) DO NOTHING;
