INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spatial', 'Spatial is a 3D gaming hub where creators craft and share immersive social experiences for web, mobile, and VR. We''re transforming online interaction from passive watching to active play. Think YouTube, but for games. From Racing Empire to Merge Survivor Zombie, there are thousands of games that can be discovered on Spatial. And with the Spatial Creator Toolkit, developers can build and publish their own games to a community of millions of players, to the library of games is growing every day.' FROM games WHERE igdb_id = 298274 ON CONFLICT (game_id, language_code) DO NOTHING;
