INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Command & Conquer: Remastered', 'A remastered version of the original Command & Conquer, part of the Command & Conquer Remastered Collection. Created by the former Westwood Studios team members at Petroglyph Games alongside the dedicated community. Every game element has been recreated in 4K detail, including the completely remastered legendary soundtrack by Frank Klepacki.' FROM games WHERE igdb_id = 128832 ON CONFLICT (game_id, language_code) DO NOTHING;
