INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Card Nation', 'Popular Indian card games at one place. Play online with your Family and Friends!  Card Nation is a collection of some best indigenous card games which most of us played in past, now you can enjoy playing these games with your Family and Friends anywhere across the globe.  Challenge your buddies and show them who rules the Card Nation!' FROM games WHERE igdb_id = 141402 ON CONFLICT (game_id, language_code) DO NOTHING;
