INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('el-hijo-a-wild-west-tale', 25227, '2020-12-03', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3jfm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb8t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'El Hijo: A Wild West Tale', 'El Hijo is a spaghetti western, indie stealth game. The game is set in a mythical place of the 19th century that very much resembles the American west, as we know it from Sergio Leone‘s westerns, taking some of its most popular characteristics of outlaw gangs, saloons, cunning, sarcasm, irony, etc. There is no indication of a specific time, or place. It could be everywhere and anywhere. You guide 6-year old boy El Hijo on his quest to find his father, by escaping a monastery, fighting his way through the desert and avoiding monstrous creatures, and outsmarting horrible gangsters in the saloon of a villain town.' FROM games WHERE igdb_id = 25227 ON CONFLICT (game_id, language_code) DO NOTHING;
