INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatsune Miku: Project Diva Mega Mix', 'Hatsune Miku: Project Diva MegaMix is a rhythm game featuring 101 songs (100 songs from the history of the series, including newly recorded songs plus the game’s newly written theme song), over 300 modules (costumes), and new game modes made specifically for Switch. 3D character models have also been updated with an anime-style touch.' FROM games WHERE igdb_id = 120278 ON CONFLICT (game_id, language_code) DO NOTHING;
