INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto x Boruto: Ninja Tribes', 'Naruto x Boruto: Ninja Tribes is based on the popular Naruto and Boruto anime series and brings together fan-favorite characters spanning multiple generations of both franchises for one-tap team-based battles. A turn-based RPG being developed by Bandai Namco, now planned for release on the Enza platform in Japan which includes PC and Mobile web browsers as well as standalone apps for iOS and Android. Original planned for release in 2018 as Naruto x Boruto: Borutical Generations, the game was delayed and eventually re-announced under a new title, Project: Tri, on May 15th 2019.' FROM games WHERE igdb_id = 106295 ON CONFLICT (game_id, language_code) DO NOTHING;
