INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fly Punch Boom!', 'It''s everything you''ve seen in your favorite anime fights: fly fast and smash your friends in the face until their expressions go all wonky; make them shoot off into collapsing buildings, krakens, killer cotton candy, or in space. Ram skyscrapers, whales and asteroids into your enemy, then fly towards them before they wake up and unleash over-the-top super moves. It''s all about the joy of punching.' FROM games WHERE igdb_id = 98110 ON CONFLICT (game_id, language_code) DO NOTHING;
