INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('labyrinth-of-galleria-the-moon-society', 126008, '2020-11-26', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co68ur.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11bs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Labyrinth of Galleria: The Moon Society', 'From the creators of Labyrinth of Refrain: Coven of Dusk comes a new chapter in the dungeon-exploring adventure filled with charm and mystery! Summoned by the magnificent Madame Marta, you are but a wandering spirit awaiting your next command. With the help of Eureka, Madame Marta’s assistant, and an army of soul-infused puppets, you are tasked with delving into the depths of a mysterious underground labyrinth teeming with enchanted monsters to unearth the Curios d''art that lie within! Labyrinth of Galleria: The Moon Society offers dungeon-crawling adventures with new quality of life improvements and 50 hours of exploration alongside a cast of fully customizable companions to do your bidding. Use a variety of pacts and puppet soldiers to customize a team of up to 40 fighters to dive into the darkness and discover the secrets with the Labyrinth of Galleria…if you dare!' FROM games WHERE igdb_id = 126008 ON CONFLICT (game_id, language_code) DO NOTHING;
