INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Room VR: A Dark Matter', 'The British Institute of Archaeology, London, 1908: The disappearance of an esteemed Egyptologist prompts a Police investigation into the unknown. Explore cryptic locations, examine fantastic gadgets and uncover an otherworldly discovery which blurs the line between reality and illusion. Designed from the ground up for the unique capabilities of virtual reality, players can inhabit the spine-tingling world of The Room and interact with its strange contraptions in this compelling new chapter.' FROM games WHERE igdb_id = 123991 ON CONFLICT (game_id, language_code) DO NOTHING;
