INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('partisans-1941', 117497, '2020-10-14', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3xwg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arppi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Partisans 1941', 'Partisans is a real-time tactical strategy with non-linear type of storytelling. This game is about soviet partisans and their activity during World war II. It’s focused on harsh reality in those times, when many people became reluctant heroes, and every feat required its price, and sometimes this price was extremely high. The game shows the war from a new, poorly explored angle. However, it is not a historical simulator, Partisans offers a unique interpretation of those times’ events. The game shows partisans’ everyday life, which is full of cold, hunger and wounds. Still there is a room for joy as well. Players would have to make tough choices, for example, they’ll have to decide whether to help civilians and betray their position or to walk past and stay unnoticed. The game give opportunities to prove oneself in a fight, to overcome the superior forces of the enemy using cunning and mother wit , and to leave the field when the situation is really bad.' FROM games WHERE igdb_id = 117497 ON CONFLICT (game_id, language_code) DO NOTHING;
