INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Captain Tsubasa: Rise of New Champions', 'A new Captain Tsubasa game is here, 10 years after the release of the previous console game! The worlds of Soccer and Anime converge in Captain Tsubasa: Rise of New Champions, based on the renowned Captain Tsubasa series. The game chronicles the athletic exploits of Tsubasa Ozora as he plays out his love for the game and advances through the ranks of multiple Soccer leagues. Captain Tsubasa: Rise of New Champions immerses players in an action packed soccer game that features exhilarating gameplay, over the top signature shots and accessible gameplay.' FROM games WHERE igdb_id = 128769 ON CONFLICT (game_id, language_code) DO NOTHING;
