INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gaia Beyond', 'Gaia Beyond is a handcrafted 2D Action-RPG, an exploration mix built around the core features fighting, mining and trading. Your decisions are footprints within a vast non-linear solar system. Forge alliances among numerous factions and develop relations with hundreds of NPCs. Focus on trading and personal interaction or embark on science missions – hunt down pirates and collect their bounty. Infiltrate dubious factions and uncover secret plots and dark menaces.' FROM games WHERE igdb_id = 86418 ON CONFLICT (game_id, language_code) DO NOTHING;
