INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Worm Jazz', 'Worm Jazz is a wriggly puzzler with a unique blend of game mechanics inspired by familiar classics such as Snake 🐍 and Bomberman 💣. You take control of Mr. Mark, an earthworm with a particular fondness for smooth jazz and dapper headwear. Wiggle your way through intricate, mind-bending mazes filled with mines, wormholes and powerups! Are you able to gobble up all the food on each stage and reach the golden apple? 🍎' FROM games WHERE igdb_id = 139368 ON CONFLICT (game_id, language_code) DO NOTHING;
