INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('destroy-all-humans--1', 119257, '2020-07-28', 67, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2g6j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar78p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destroy All Humans!', 'A remake of Destroy All Humans!, an action-adventure video game that stands as the inaugural entry in the Destroy All Humans! franchise. It unfolds in 1959 in the United States. The game satirises the lifestyles, pop culture, and political attitudes of that era. Players take on the role of Cryptosporidium 137, a member of the fictional alien race known as "Furons." Functioning as a Furon spy hitman, Cryptosporidium 137 invades Earth with the mission of harvesting human DNA to sustain the cloning process for his species. The remake features new missions, control schemes, upgrades, skins, abilities, and graphical enhancements.' FROM games WHERE igdb_id = 119257 ON CONFLICT (game_id, language_code) DO NOTHING;
