INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sometimes Always Monsters', 'Sometimes Always Monsters is a narrative roleplaying life simulator filled with choices.  You play a recently married author who joins a cross-country bus tour to promote your next upcoming novel. Along the way, you hear about vicious rumours claiming you''re a total fraud.  As you journey through five unique cities, meet fans and critics alike, and make friends with your fellow busmates, it''ll be your choices that help unravel the conspiracy laid against you.' FROM games WHERE igdb_id = 20122 ON CONFLICT (game_id, language_code) DO NOTHING;
