INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danger Grid', 'Danger Grid takes you on an adventure through a retro futuristic universe of pixelated environments, low poly spaceships, killer robots, aliens, and glowing neon lights. Explore the grid, a large procedural universe of near infinite (ok, not really) dimensions, jumping through the Gateway to nearby worlds. Trade commodities, mine resources, and make a profit. Upgrade your shield and lasers and blast through the Danger Grid.' FROM games WHERE igdb_id = 107309 ON CONFLICT (game_id, language_code) DO NOTHING;
