INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('solasta-crown-of-the-magister', 120170, '2020-10-20', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qu4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5u9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solasta: Crown of the Magister', 'Discover the shattered world of Solasta: explore ruins and dungeons for legendary treasures, learn the truth of an age-old cataclysm - and stop it from happening again. Create your very own party of adventurers with our Character Creation Tool in the classic tabletop RPG tradition. Breathe life into your heroes, and see their personalities reflected in their dialogue. Tailor your squad to your preferred strategy and maximize your party''s abilities. The choice is yours. Delve into long forgotten dungeons to unearth ancient artifacts, but stay watchful of light and darkness: many dangers hide in the dark, but a light can attract monsters. Some enemies have darkvision, some may flee from your torch... Successful adventurers will learn to use it to their advantage. Fight monsters in squad-level, turn-based, tactical combat. Solasta''s dynamic environment offers some interesting tactical options. Bridges can collapse, leaving enemies stranded and vulnerable. Walls and columns can be pushed over - on top of your foes, if you do it right. The world is your playground.' FROM games WHERE igdb_id = 120170 ON CONFLICT (game_id, language_code) DO NOTHING;
