INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Witch Academia: VR Broom Racing', 'Take to the skies on a magical broom in the VR racing game based on the Little Witch Academia anime! Join the ranks of students at prestigious Luna Nova Witchcraft Academy to race through the skies and purify ghosts on a custom broom in more than a dozen missions, and experience original story sequences featuring voice actors from the hit anime series! Collect items, points, and tickets, and customize your broomstick to your heart’s content. Can you take first place in the ultimate challenge of the Stella Cup? Join together with friends in online multiplayer and take in the sights of the world of Little Witch Academia in Free Flight Mode! “Together, we can fly!"' FROM games WHERE igdb_id = 139341 ON CONFLICT (game_id, language_code) DO NOTHING;
