INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('soul-azylum', 131379, '2020-04-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2pao.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc80kk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soul Azylum', 'Challenge the other players by escaping from an old village where the population wishes your death. Cunning to draw the villagers'' attention to your opponents in order to take advantage of a moment of respite and successfully extricate yourself! FIGHT THE OTHER PLAYERS! Released to your sad fate in a dismal village with a population more than strange and violent. Show your courage, cunning and anticipation in order to emerge victorious from these meetings! Be the first to collect the keys to a vehicle that will allow to escape this dangerous area! Not armed, the decor elements will be your best allies: attract the attention of enemies to other players, block certain passages, block doors to prevent a player from taking shelter ...! WILL YOU BE ABLE TO FIGHT SOLO MODE? In solo mode, start on the outskirts of a village that seems deserted. Find something to repair your car in this aging place that will quickly appear less uninhabited than expected ... Without a weapon to defend yourself, complete the missions given by a young woman, prisoner of this place. Find something to restart your vehicle to escape!' FROM games WHERE igdb_id = 131379 ON CONFLICT (game_id, language_code) DO NOTHING;
