INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HalfLight', 'Halflight is a 3D adventure game set in a fictional world of 1940s Taiwan with classic puzzles. Players follow in the steps of the young boy Xi-sheng as he strays into an extraordinary phantom world -- a world where Memories intertwine with Nightmares, Hope casts its lot with Destiny, and any semblance of self-identity will be tested.' FROM games WHERE igdb_id = 83971 ON CONFLICT (game_id, language_code) DO NOTHING;
