INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-game-of-thrones-the-board-game-digital-edition', 139376, '2020-10-06', 72, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wl0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arly8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Game of Thrones: The Board Game - Digital Edition', 'A Game of Thrones: The Board Game – Digital Edition is the digital adaptation of the top-selling strategy board game from Fantasy Flight Games. During the game, players spread their influence across Westeros through a combination of strategic planning, masterful diplomacy, and military might. As one of the Great Houses, will you conquer with force, forge alliances, rally your townsfolk, or cunningly coerce your way to the Iron Throne? Based on the best-selling A Song of Ice and Fire series of fantasy novels by George R.R. Martin, A Game of Thrones: The Board Game – Digital Edition allows up to six players to play online, or a single player with up to five AI opponents to play locally. The game is set after the death of King Robert Baratheon and allows each player to assume the role of one of the Great Houses of the Seven Kingdoms in an attempt to assault King’s Landing and claim the Iron Throne. To be declared ruler of the Seven Kingdoms, you have 10 rounds to use diplomacy and warfare to your advantage to control as many strategic areas of the map. Conquer with care as your resources are scarce and your troops are not expendable. Muster your army, plan your orders wisely and seize strategical lands with your Footmen, Knights, Siege Engine and ships. During the turmoil of a battle, use well-known characters from your house to take the upper hand and vanquish your enemies.' FROM games WHERE igdb_id = 139376 ON CONFLICT (game_id, language_code) DO NOTHING;
