INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('9-monkeys-of-shaolin', 94078, '2020-10-16', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xlo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xbzlcjqw88uzwlv1t2ji.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '9 Monkeys of Shaolin', '9 Monkeys of Shaolin marks a true rebirth of the iconic brawler genre in vein of old-school video games. If, as a kid you had hours of fun playing SNES or SEGA beat ''em up videogames crushing foes left and right then this new title from the creators of hardcore brawler REDEEMER is definitely for you! As a mere Chinese fisherman Wei Cheng you have to avenge the death of your friends and family slaughtered in a pirate raid at your peaceful village. Game protagonist is quite a tough nut to crack as he knows the basics of ancient martial arts only mastered by legendary Shaolin monks. Get your trusty battle staff ready for a challenging adventure in Medieval China and for merciless fights with hordes of various enemies. Action-packed battles, user friendly controls and incredible atmosphere of great kung-fu movies of 70s – all this makes 9 Monkeys of Shaolin a perfect choice for every true fan of really hardcore brawlers.' FROM games WHERE igdb_id = 94078 ON CONFLICT (game_id, language_code) DO NOTHING;
