INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Umurangi Generation', 'Umurangi Generation is a first person photography game in the shitty future. Set in Tauranga Aotearoa off the back of an impending crisis you are a courier for the Tauranga Express. Along the way you take photos to make ends meet. Throughout the game you will unlock a variety of lenses and equipment.' FROM games WHERE igdb_id = 131631 ON CONFLICT (game_id, language_code) DO NOTHING;
