INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Night Fisherman', 'The English Protection Group keep a watchful eye on the Smuggler''s Run, a renowned crossing for vessels bound from Calais containing illegal immigrants.  When faced with an armed man, his voracious appetite for conversation, and nobody else for miles, can you safely get rid of him?  This is a single, film-like scene. You direct the fisherman''s actions, as well as directing the camera shots between the cinematic angles available.  The first of twelve small, experimental narrative games to be released monthly.' FROM games WHERE igdb_id = 134493 ON CONFLICT (game_id, language_code) DO NOTHING;
