INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ancient-enemy', 111842, '2020-04-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1io6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4sm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancient Enemy', 'An unusual, strategic RPG card game from the makers of Shadowhand and Regency Solitaire. "Awakening from centuries of slumber, a fallen mage returns to battle twisted folkloric foe across sprawling, ghostly landscapes. His ultimate destination: the nameless antagonist, a dread nemesis waiting patiently in the dark fastness of monstrous citadel, his Ancient Enemy. You''ll embark upon a quest inspired by British mythology and Mabinogion, so expect card battling, visceral fights, mixed with bleak and evocative folklore! Loot the fallen to fill your hero''s RPG-style inventory with collectible cards, capture strongholds and gather talented henchmen. Only powerful magic and iron determination will enable revenge upon your ultimate foe."' FROM games WHERE igdb_id = 111842 ON CONFLICT (game_id, language_code) DO NOTHING;
