INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Katana Kami: A Way of the Samurai Story', 'The Way of the Samurai is forged in battle! Play as a ronin during Japan''s Meiji Restoration in the volatile Rokkotsu Pass. The swordsmith Dojima falls into debt and his beautiful daughter is taken as collateral. Help repay the debt by crafting swords by day and exploring the mysterious, twisting dungeons of the Ipponmatsu Cave for valuable materials at night.' FROM games WHERE igdb_id = 125296 ON CONFLICT (game_id, language_code) DO NOTHING;
