INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Probe', 'A challenging 2D block breaker featuring arcade elements and a modern spin on the popular retro game. Destroy data blocks and galactic enemies using only your probe, bullets and power ups but don''t lose your ball to the void. Do you have what it takes to reach the end of the universe? Features: -50 Unique and challenging levels -6 Power-ups to combine and utilize -XBOX Controller Support -80+ Steam Achievements -Gameplay Statistics (In-Game) -Steam Leaderboards and Scoring System' FROM games WHERE igdb_id = 133057 ON CONFLICT (game_id, language_code) DO NOTHING;
