INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disintegration', 'In Disintegration, you play an Integrated character named Romer. He’s one of many who rebelled and are now outlawed by the Rayonne. It’s up to you to lead a small group of these Outlaws, people who have chosen to fight back and survive, into a brighter future where we protect those they care about and hope to one day become human again.' FROM games WHERE igdb_id = 120625 ON CONFLICT (game_id, language_code) DO NOTHING;
