INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil May Cry 5: Special Edition', 'Devil May Cry 5: Special Edition features improved visuals and gameplay at up to 120 frames per second. Alongside all previously-released downloadable content, other additions include Vergil as a playable character, ray tracing graphics options, and two additional game modes: Legendary Dark Knight mode, which significantly increases the number of enemies in each level, and Turbo mode, which increases the game speed by 20%.' FROM games WHERE igdb_id = 138932 ON CONFLICT (game_id, language_code) DO NOTHING;
