INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skully', 'Fate has bestowed Skully a second chance at life when an enigmatic deity reanimates the skull through the power of magical clay after it washes upon the shore of a secluded isle. Skully must hop, skip, and roll through this diverse island habitat teeming with obstacles and puzzles to intervene in a feud between the deity’s three siblings whose quarrel jeopardizes the place they call home.' FROM games WHERE igdb_id = 133902 ON CONFLICT (game_id, language_code) DO NOTHING;
