INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ho-Ho-Home Invasion', 'In Ho-Ho-Home Invasion (very nearly titled Santa Game Solid), play as Santa preparing his stealth skills ahead of the big night (Christmas Eve), delivering presents under trees, filling stockings, and making a swift exit - without getting caught! Whitepot Studios is excited to announce this free festive stealth micro-game, created especially for the festive season.' FROM games WHERE igdb_id = 141655 ON CONFLICT (game_id, language_code) DO NOTHING;
