INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadly Premonition 2: A Blessing in Disguise', 'Deadly Premonition 2: A Blessing in Disguise is a sequel to Deadly Premonition that takes place in present-day Boston. Through unique storytelling, venture back in time to Le Carré and uncover the mysteries buried within the once peaceful town. Serving as both a sequel and prequel to the original Deadly Premonition, follow Agents Davis and Jones as they begin a new investigation into the Le Carré serial murders. Through the memories of a former FBI agent, go back in time to Le Carré and step into the role of Special Agent York to begin unraveling the mystery.' FROM games WHERE igdb_id = 122232 ON CONFLICT (game_id, language_code) DO NOTHING;
