INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ensemble Stars!! Music', 'Ensemble Stars!! Music is the 3D rhythm game and 2nd game after the split. As the player, you play various songs on different difficulties, gather cards by gacha/scouting, and level the boys up in ranks. By unlocking more and more of each card, they''ll become more powerful, with some having side stories, backgrounds, outfits (2DLive and/or 3D), special performances, and "blooming" the card (awakened).' FROM games WHERE igdb_id = 145907 ON CONFLICT (game_id, language_code) DO NOTHING;
