INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('victory-road', 131819, '2020-03-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20mv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar55z7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Victory Road', 'Victory Road is a boxing simulator that uniquely puts you in the role of the coach, not the boxer! As a coach, the fate of your boxer’s career, and potentially his life, is in your hands. Raise your boxer and utilize various strategies to climb up the ranking board.  In Victory Road, players will assume the role of a boxing coach and meticulously plan each day’s training and meals. Players will be able to customize their boxer through adjusting his training routine to emphasize the growth of specific stats, altering his fighting style, and changing his equipment and special techniques. Matches take place in real-time using a fighting game-inspired engine, and can be won or lost depending on the advice shouted to your boxer. Boxers will gradually learn unique fighting styles, combos, and techniques depending on how the player guides him.' FROM games WHERE igdb_id = 131819 ON CONFLICT (game_id, language_code) DO NOTHING;
