INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('professor-lupo-ocean', 133081, '2020-10-05', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3y0l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb7g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Professor Lupo: Ocean', 'You wake up in the middle of a crumbling spaceship and yet, somehow, everything’s flooded... You''re at the bottom of the Ocean! The ship computer keeps giving you never-ending tasks to repair the ship and is saying you’re a... Clone? The adventure’s only just begun! Welcome to Professor Lupo: Ocean, the epilogue of the Professor Lupo and His Horrible Pets saga. At the end of the original game, we left our heroes at the start of a long journey. Five thousand years later, the Aurora space station has reached its destination. Clone, our new heroine, will need to find out how it ended up underwater and just what happened to all of its crew. We bring back the gameplay of the first game and add a new element: water. This element is instrumental and influences each and every aspect of the game. Key points: - 40 new levels - Ro the Furax, a friendly character who’ll help you out during the adventure - Learn how new aliens behave and use them in your favour - Plot twists that tie you back to the original game Will you be able to escape?' FROM games WHERE igdb_id = 133081 ON CONFLICT (game_id, language_code) DO NOTHING;
