INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ponpu', 'Get ready to break some eggs in this frantic multiplayer party-game! Ponpu mixes classic gameplay with new crazy mechanics, all packaged in one of the coolest art-styles ever seen! Features: - A fresh take on a classic game concept - An epic campaign with massive bosses - Hectic 4-player multiplayer with three game modes: 1. Deathmatch – Last Ponpu standing wins! 2. Coin Steal – Hoard the most coins before the time is up. Dragon style! 3. Paint Battle – Paint the town red! (or you know… whichever color you prefer) - The most epic egg-based arsenal ever witnessed!' FROM games WHERE igdb_id = 132777 ON CONFLICT (game_id, language_code) DO NOTHING;
