INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob SquarePants: Battle for Bikini Bottom - Rehydrated', 'Are you ready, kids? The cult classic is back, faithfully remade in spongetastic splendor! Play as SpongeBob, Patrick and Sandy and show the evil Plankton that crime pays even less than Mr. Krabs. Want to save Bikini Bottom from lots of rampant robots with your mighty bubbles? Of course you do! Want to underpants bungee jump? Why wouldn''t you! Want to join forces in a brand new multiplayer mode? The battle is on!' FROM games WHERE igdb_id = 119239 ON CONFLICT (game_id, language_code) DO NOTHING;
