INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Café Mix', 'Complete touch-based puzzles to serve dishes and drinks to adorable Pokémon customers! Link together Pokémon icons to clear puzzles as you work to build up your very own café in Pokémon Café Mix, a free-to-start game for the Nintendo Switch system! Meet the goals for each puzzle before you run out of turns—link a certain number of icons, get a high score, or even destroy sugar cubes to serve up Pokémon themed menu items.' FROM games WHERE igdb_id = 135233 ON CONFLICT (game_id, language_code) DO NOTHING;
