INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Missing Few', '11 years after the disappearance of his son, Jack Norwood is brought back to the rural town of Staten. A call from an old friend Scott Clarke lead detective on your son''s case brings you back home. As Jack follows the trail to unearth the truth, he might find out things have never been what they appeared in Staten.  Search the enigmatic rural town of Staten to learn the truth and find out who or what is behind the mystery.' FROM games WHERE igdb_id = 110808 ON CONFLICT (game_id, language_code) DO NOTHING;
