INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('terrorarium', 115014, '2020-07-28', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cfy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arluo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Terrorarium', 'Terrorarium is an action puzzler game about wanton destruction & adorable gore across a galaxy of community-designed murder gardens. Like every great villain, you have been foiled for the last time. And this time you mean it. Those fools at the Intergalactic Horrorcultural Society have given the blue ribbon -- your blue ribbon -- to some ill-deserving pretender to the throne for too many star cycles now, and you are determined it will not happen again. This time, you''re pulling out all the stops. There is no monster too deadly for you to capture, no combination of creatures too volatile for you to control. You don''t care how many invasive species you have to introduce or ecosystems you have to destroy, your ambition will not be contained. You will slay the competition at any cost. Terrorarium is an 3D puzzle platformer where you play as the Gardener, a feisty granny with a chip on her shoulder, and her army of adorable, expendable Moogu. The Moogu will die frequently, breed out of control, and are often as insufferable as they are useful. In Maker Mode, you choose how the chaos unfolds. Design and publish your own levels with vicious creatures, treacherous hazards, plant monsters, lovely foliage, and destructible terrain. With these moveable, scalable, customizable assets, you can create a beautiful garden, a deadly maze or a murderous gauntlet. Hundreds of community levels have already been designed for you and you can share the levels you build with your friends and frenemies, so they too may see the horrors you have wrought.' FROM games WHERE igdb_id = 115014 ON CONFLICT (game_id, language_code) DO NOTHING;
