INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swallow the Sea', 'Take a short surreal swim. You are a lowly egg cell journeying through a swollen sea of strange and humanoid fish. Prey on smaller life, growing larger and stronger to perhaps someday be born. Swallow the Sea was developed by Maceo bob Mair and Nicolás Delgado. Sound Design by Pato Flores and Chris Dang and Composed by Publio Delgado.' FROM games WHERE igdb_id = 133836 ON CONFLICT (game_id, language_code) DO NOTHING;
