INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pendragon', 'Pendragon is a turn-based strategy game, where every move you make drives the narrative, and every story twist opens new gameplay opportunities. Will you advance and show your mettle, or cautiously retreat? Will you slip round enemies, or encounter them head-on? And when sacrifices are required, who will you put in harm''s way?' FROM games WHERE igdb_id = 132903 ON CONFLICT (game_id, language_code) DO NOTHING;
