INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyond a Steel Sky', 'From Charles Cecil, creator of the Broken Sword series, with art direction by Dave Gibbons, legendary comic book artist behind ‘Watchmen’, comes ‘Beyond a Steel Sky’, the long awaited sequel to the cult classic ‘Beneath a Steel Sky’. ‘Beyond a Steel Sky’ is a dramatic, humorous, cyberpunk thriller in which engaging puzzles drive a fast-paced narrative set in a dynamic gameworld that responds to – and is subverted by – the player’s actions.' FROM games WHERE igdb_id = 116634 ON CONFLICT (game_id, language_code) DO NOTHING;
