INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('broken-lines', 107175, '2020-02-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xgp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ard4x.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Lines', 'Broken Lines is a war-game with a serious story, told from the perspective of the individual soldiers. A game for people who likes real-time tactics and strategy games, but are too slow to play them. Give orders to you men, while in pause - and total control. Then see the execution in real-time - sometimes resulting in catastrophic failure. Play the campaign with randomized missions and non-linear stories. Select and equip your squad. Train them in unique combat skills and perks. Plan your turn in pause mode and see it play out in real-time. Use cover and flanking to overcome the opposition. Rewind the level to avoid casualties and achieve better loot. Manage resources and survive until you either find your way out of the valley or lose your way and your conscience in the process.' FROM games WHERE igdb_id = 107175 ON CONFLICT (game_id, language_code) DO NOTHING;
