INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mary-skelter-finale', 131974, '2020-11-05', 87, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wct.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11cf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mary Skelter Finale', 'Mary Skelter Finale is a first-person dungeon crawling RPG with grid-based movement and a turn-based combat system. Characters are based on fairy tales but the game has a job system allowing for skill customization. The story is about attempting to break out of a nightmarish prison. A new feature to the series allows the player to control multiple groups across the dungeons in order to progress. There are 6 preset groups of 4-7, with over 30 characters. Mary Skelter Finale is set to be the end of the Mary Skelter story and has included a feature to re-watch/read story scenes from the main and side scenarios for both of the previous games, though the voiceovers aren''t included. It also includes a side story made ahead of the first game and the visual novel included as a pre-order bonus of the second game. The extra content also includes a Gallery mode to view video and CG scenarios or background art. A music mode for the background music and a character mode to view the different characters information.' FROM games WHERE igdb_id = 131974 ON CONFLICT (game_id, language_code) DO NOTHING;
