INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Necrobarista', 'Necrobarista is a gorgeous 3D visual novel about a supernatural Melbourne cafe where the dead spend their last night on Earth. Utilizing a unique anime-inspired aesthetic, Necrobarista places a focus on the usage of animation and cinematography to provide a cinematic experience that draws players into a visually and narratively captivating adventure. Through a series of vignettes, Necrobarista presents a story told from the viewpoints of a diverse cast of characters, and explores the supernatural underworld of Melbourne''s cafe scene.' FROM games WHERE igdb_id = 26870 ON CONFLICT (game_id, language_code) DO NOTHING;
