INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('little-orpheus', 55068, '2020-06-12', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7wqr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzue.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Orpheus', 'An impossible adventure awaits in Little Orpheus, the brand-new adventure from award-winning studio The Chinese Room, a Sumo Digital Studio, available from today exclusively on Apple Arcade. From the BAFTA-winning team behind Everybody’s Gone to the Rapture and Dear Esther, Little Orpheus is a side-scrolling adventure game about one comrade’s journey to the centre of the Earth. The year is 1962. NASA are trying to put a man on the moon but in a remote corner of Siberia, a Soviet cosmonaut is heading in the other direction. Ivan Ivanovich is dropped into an extinct volcano in his exploration capsule, Little Orpheus, to explore the centre of the earth. Ivan vanishes, emerging three years later claiming to have saved the world. In a top-secret bunker, he is debriefed by the fearsome General Yurkovoi. Little Orpheus casts players as Ivan as he recounts an adventure beyond belief: a tale of lost civilizations, undersea kingdoms, and prehistoric jungles deep below the Earth’s crust. Brought to you in glorious technicolour with visuals inspired by a bygone era of adventure, Little Orpheus is a serialised adventure inspired by classic movies like Flash Gordon, Sinbad and The Land That Time Forgot.' FROM games WHERE igdb_id = 55068 ON CONFLICT (game_id, language_code) DO NOTHING;
