INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bugsnax', 'Bugsnax takes you on a journey to Snaktooth Island, home of the legendary half-bug half-snack creatures, Bugsnax. Invited by intrepid explorer Elizabert Megafig, you arrive to discover your host nowhere to be found, her camp in shambles, and her followers scattered across the island alone... and hungry! It''s up to you to solve the mysteries of Snaktooth Island: What happened to Lizbert? What are Bugsnax and where do they come from? But most of all, why do they taste SO GOOD?' FROM games WHERE igdb_id = 134602 ON CONFLICT (game_id, language_code) DO NOTHING;
