INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vibrant Venture', 'Vibrant Venture is a singleplayer 2D adventure platformer game featuring a quirky cast of characters! The game features four playable characters with multiple unique abilities that can be combined for extremely versatile, fluid and fun movement! The main focus of the game is traditional platforming combined with responsive and open-ended controls in a challenging environment which constantly gives the player fun and rewarding experiences. This also means there are often multiple ways to clear different sections!' FROM games WHERE igdb_id = 127991 ON CONFLICT (game_id, language_code) DO NOTHING;
