INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost of Tsushima', 'Uncover the hidden wonders of Tsushima in this open-world action adventure. Forge a new path and wage an unconventional war for the freedom of Tsushima. Challenge opponents with your katana, master the bow to eliminate distant threats, develop stealth tactics to ambush enemies in order to win over the mongols.' FROM games WHERE igdb_id = 75235 ON CONFLICT (game_id, language_code) DO NOTHING;
