INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel''s Iron Man VR', 'In Marvel''s Iron Man VR the player, who plays as the genius inventor Tony Stark, confronts ghosts from his past—powerful forces who seek to ruin him and everything he stands for. By fully embracing the magic of PlayStation VR, players will come face-to-face with iconic allies and Super Villains as they jet around the globe on a heroic mission to save not only Stark Industries, but the world itself.' FROM games WHERE igdb_id = 116585 ON CONFLICT (game_id, language_code) DO NOTHING;
