INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nioh 2', 'Master the lethal arts of the samurai as a mysterious half-human, half-supernatural Yokai warrior, in this challenging action RPG sequel. Explore violent Sengoku-era Japan and the deadly Dark Realm, both plagued with grotesque, merciless demons. Unsheathe your deadly weapons and cut down all enemies in your path using a revamped combat system and the ability to transform into a full Yokai to unleash devastating paranormal powers.' FROM games WHERE igdb_id = 103330 ON CONFLICT (game_id, language_code) DO NOTHING;
