INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ostranauts', 'Ostranauts is a detailed simulation of owning and living aboard a spaceship, in a solar system where honest living is a slow death sentence. Set in the NEO Scavenger universe, where Earth has suffered cataclysmic collapse, the rest of the System lives on in a state of capitalistic dystopia. Players will create their captain, build or customize their starting ship from the spoils of their career history, and find ways to keep fuel in their tanks, food on their plates, and the debt collectors at bay.' FROM games WHERE igdb_id = 115299 ON CONFLICT (game_id, language_code) DO NOTHING;
