INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Necromunda: Underhive Wars', 'Necromunda: Underhive Wars is a turn-based tactical RPG. Rival gangs of ruthless warriors are locked in an endless war for control of the Underhive, a gigantic warren of derelict factories, rusted metal husks, and forgotten technologies. Anarchy, violence, betrayal and death rule this hellish place, long forsaken by any semblance of civilization.' FROM games WHERE igdb_id = 26846 ON CONFLICT (game_id, language_code) DO NOTHING;
