INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Othercide', 'Othercide is a horror themed tactical turn-based game set in an esoteric world beyond our reality. The game will place the player in control of female warriors, in a desperate struggle to push back nightmarish creatures and prevent reality from shattering. Using only black, white and touch of red, the game will drag players into a whole new universe for the genre, to experience a journey through a strange and unknown world, a world that lays behind the mirror of their own minds.' FROM games WHERE igdb_id = 107140 ON CONFLICT (game_id, language_code) DO NOTHING;
