INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iron Danger', 'Iron Danger is a tactical combat game with a unique time manipulation mechanic. A never before seen combination that combines the tactical depth of turn-based games with the exciting action of real-time games. Tackle challenging encounters with your party of two characters, using a variety of skills and highly interactive environments. Maybe you will set an enemy on fire and kick them into a grain field for a proper barbeque, or set up a trap and fell a tree on top of them. The options are endless and it is you who will be deciding your own approach!' FROM games WHERE igdb_id = 101065 ON CONFLICT (game_id, language_code) DO NOTHING;
