INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1971 Project Helios', '1971 Project Heliosis a turn-based strategy game which combines modern warfare military tactics and close combat. Firearms and vehicles are scarce, conflicts and hostilities have no end, and the terrible freezing cold annihilates friends and foes in its path.' FROM games WHERE igdb_id = 124919 ON CONFLICT (game_id, language_code) DO NOTHING;
