INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crucible', 24653, '2020-05-20', 67, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25a2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arw0c.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crucible', 'Crucible is a team-based action shooter driven by the choices you make. Each match in Crucible is a fight for survival and control. Not only will you be going toe-to-toe with your fellow competitors, but you’ll have to adapt and overcome all the challenges the planet itself throws your way. You and your teammates will need to work together to take down alien creatures, capture objectives, and pursue your opponents in search of victory. After its May 20th launch and pre-season that lasted till June, Crucible switched to closed beta in July to adjust the game based on user feedback with scheduled community events and tournaments. On October 9th it was announced that development would be discontinued and the team would transition to working on New World and other upcoming projects. There will be a final playtest and community event before match making is taken offline leaving custom games the only available mode till the servers are shutdown on November 9th.' FROM games WHERE igdb_id = 24653 ON CONFLICT (game_id, language_code) DO NOTHING;
