INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minecraft Dungeons', '"Brave the dungeons alone, or team up with friends! Up to four players can battle together through action-packed, treasure-stuffed, wildly varied levels, all in an epic quest to save the villagers and take down the evil Arch-Illager! Discover new weapons and items that will help you defeat a ruthless swarm of new-and-nasty mobs. Fight or flee through canyons, swamps and – of course – mines! Any adventurer brave or foolish enough (or a bit-of-both!) to explore this blocky and beautiful world will need to come prepared. So quickly, gear up!"' FROM games WHERE igdb_id = 110474 ON CONFLICT (game_id, language_code) DO NOTHING;
