INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airborne Kingdom', 'Take a fantastical journey - fly the desert and build your domain. Airborne Kingdom uniquely blends city management and exploration, with a world and lore all its own. Build housing, gather food, satisfy needs, and grow your tribe. Maintain lift, discover resources, and explore the desert for lost technologies. The kingdom, your journey, their lives - all of it is up to you to decide.' FROM games WHERE igdb_id = 115473 ON CONFLICT (game_id, language_code) DO NOTHING;
