INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('morkredd', 100157, '2020-12-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2knb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxzx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Morkredd', 'The Orb is your fate. Morkredd is a tense, physics-based co-op puzzle game for one to two players combining skill-based puzzle-solving, a challenging balance of light and shadow, and a dark world full of secrets to unlock. The Orb Calls for Two: Morkredd is best played as a couch co-op experience. Heed the Orb’s call with a friend or prove your loyalty alone by mastering the unique dual-character controls. Your Path is the Orb: You are the Orb’s protector, and the Orb’s light is yours. Survive and master over 60 puzzles while avoiding the shadows caused by your partner and the environment. The Orb is Your Only Friend: An endless abyss of deadly shadows conceal dangers in this cold, dark world. Stay with the Orb if you want to stay alive. Gaze into the Orb: Discover ancient secrets about the Orb hidden in the darkness.' FROM games WHERE igdb_id = 100157 ON CONFLICT (game_id, language_code) DO NOTHING;
