INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil May Cry 3: Dante''s Awakening - Special Edition', 'An HD remaster of Devil May Cry 3: Dante''s Awakening - Special Edition. This edition includes all of the Special Edition content, including the ability to play as Vergil, and even includes extra bonus features exclusive to the Nintendo Switch, such as "Free Style mode," which enables you to switch freely between fighting styles; the abilty to switch between all unlocked weapons at any time; and finally, play "Bloody Palace mode" in local co-op. Set before the events of the original Devil May Cry, this action classic sees Dante facing off against his twin brother, Vergil, who has designs on unlocking a gate to the demonic realm, to which Dante himself holds the key.' FROM games WHERE igdb_id = 218390 ON CONFLICT (game_id, language_code) DO NOTHING;
