INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash Bandicoot 4: It''s About Time', 'Crash Bandicoot 4: It''s About Time is the eighth Crash Bandicoot series game, though the fourth chronologically. The game retains the series'' core platforming gameplay and adds new elements through the use of the Quantum Masks, who can alter levels and provide means to traverse or overcome obstacles. It also includes additional game modes for replaying levels, and the ability to control five characters, three of whom – Cortex, Dingodile, and Tawna – have their own unique gameplay and levels.' FROM games WHERE igdb_id = 135254 ON CONFLICT (game_id, language_code) DO NOTHING;
