INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Monster''s Expedition', 'A Monster’s Expedition (Through Puzzling Exhibitions) is a brand new adventure tour for monsters who love to learn about humans! Learn the ancient art of pushing trees over* and fashion your own pathways with our easy-build bridges. Then immerse yourself in human culture with all-new exhibits from our "Human Englandland" dig site, each accompanied with expert insights**! *Trees have been pre-weakened by our experts for your convenience. **Insights is not a legally binding term and may or may not include idle speculation, rumour and hearsay.' FROM games WHERE igdb_id = 131845 ON CONFLICT (game_id, language_code) DO NOTHING;
