INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hiveswap: Act 2', 'Joey Claire is stranded on a planet of alien teenagers, armed with her best dancin'' shoes and a sylladex full of pogs. It’s up to her to survive on the dangerous planet of Alternia and get home with the help of her new friend Xefros, a novice at telekinesis and a fairly decent rapper.' FROM games WHERE igdb_id = 125164 ON CONFLICT (game_id, language_code) DO NOTHING;
