INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Fetchers', 'Star Fetchers: Pilot is part 1 of a journey following two inner city thugs as they take on the hardest gangster there ever was. Star Fetchers is an adventure huffing on the fumes of 90''s midnight TV, delivering a story paved with bizarre scenarios, ugly characters and high paced action. Follow the gang "The Thornz" as they crawl out of the slum and make it to the top.' FROM games WHERE igdb_id = 126573 ON CONFLICT (game_id, language_code) DO NOTHING;
