INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR Heat 5', 'NASCAR Heat 5, the official video game of the world’s most popular stockcar racing series, puts you behind the wheel of these incredible racing machines and challenges you to become the 2020 NASCAR Cup Series champion. Features all the official teams, drivers and cars from the three NASCAR National Series as well as the Xtreme Dirt Tour, racing on 39 authentic tracks. The immersive Career is complemented by Quick Race, a new Test Session mode and multiplayer, both online and split screen.' FROM games WHERE igdb_id = 134370 ON CONFLICT (game_id, language_code) DO NOTHING;
