INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lightmatter', 'Lightmatter is an atmospheric first-person puzzle game where shadows kill you!  "The floor is lava" but with shadows that kill you!  Use lateral thinking to solve mind-bending puzzles with lights and shadows  Compelling sci-fi narrative delivered by famous voice actor David Bateson  Unique comicbook style with gloomy sci-fi atmosphere  "If LIMBO and Portal had a weird baby ..."  Inspired by games such as The Talos Principle, Portal, The Turing Test and Antichamber.' FROM games WHERE igdb_id = 113150 ON CONFLICT (game_id, language_code) DO NOTHING;
