INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resonark X', 'RESONARK X is an unprecedented rhythm game that offers a different way to play on the desktop and in VR. In desktop mode, the game is played using 7 lanes + alpha and the corresponding keyboard keys. In VR mode, you use hand controllers to clap your hands, manipulate six strings. The performance will be performed while the music is being played.' FROM games WHERE igdb_id = 141900 ON CONFLICT (game_id, language_code) DO NOTHING;
