INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secret Government', 'A game in the genre of turn-based strategy about a secret society that has been ruling humankind from the shadows for hundreds of years. And that is the main feature of the game: you’re going to lead not just a country, as is usually the case, but the organization dominating the whole world: The Brotherhood.' FROM games WHERE igdb_id = 110178 ON CONFLICT (game_id, language_code) DO NOTHING;
