INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Train', 'Hell has frozen over. Only you can protect the final burning pyre from the forces of heaven and restore the inferno. Monster Train brings a new strategic layer to roguelike deckbuilding, with three vertical playing fields to defend. Includes the released updates Wild Mutations and Friends & Foes! No playthrough is ever the same, it’s a fresh challenge every time. You’ll never play the same deck twice!' FROM games WHERE igdb_id = 129483 ON CONFLICT (game_id, language_code) DO NOTHING;
