INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foregone', 'Foregone is a fast and fluid 2D action-platformer packed with legendary loot and stunning pixel art. Collect an arsenal of powerful weapons and unravel a compelling story of regret and conspiracy as you slice your way through hordes of enemies to save Calagan. Available on Nintendo Switch, PlayStation 4, XboxOne and PC.' FROM games WHERE igdb_id = 116484 ON CONFLICT (game_id, language_code) DO NOTHING;
