INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Summer''s End: Hong Kong 1986', 'A Summer’s End - Hong Kong 1986 is a visual novel game. Follow the story of Michelle and Sam, and how their chance meeting evolves into a deeper romantic relationship. A Summer’s End is a romance story between two women. Set in vibrant Hong Kong in the year 1986, it is an original story about love, family, and culture. Inspired by Hong Kong cinema, 80s anime, and city pop, A Summer’s End - Hong Kong 1986 is a visual delight for fans of retro art and fashion.' FROM games WHERE igdb_id = 131912 ON CONFLICT (game_id, language_code) DO NOTHING;
