INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Table Manners', 'Swipe right for the brand new crazy physics-based dating simulator, Table Manners! Tonight''s the night, you''ve secured a date and you''re off to the most glamorous restaurant you know, there''s only one problem - you''re a disembodied hand with a knack for catastrophe! From humble restaurants to sushi bars, ice bars and even a plane - each venue contains a number of unique gameplay mechanics and challenges that you must navigate in order to impress your date. As your reputation grows you will unlock more and more potential dates with even more sophisticated challenges and dating scenarios.' FROM games WHERE igdb_id = 124000 ON CONFLICT (game_id, language_code) DO NOTHING;
