INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sheepo', 132631, '2020-08-26', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2gpx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrdn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sheepo', 'Sheepo is a quirky metroidvania platformer featuring a shape-shifting sheep-thing, who must traverse an uncharted planet in order to collect samples of each living species for an intergalactic species database. To capture a creature, Sheepo must find their unhatched egg, which happen to be highly guarded by that species "queen" (aka, a boss.) With each egg Sheepo collects, you then gain the ability to transform into that creature on contact, and explore the deeper reaches of the planets sprawling environment Sheepo is a metroidvania, but contains no standard combat. Instead, gameplay is based on platforming and exploration. With the collection of each creature, Sheepo is able to dig, fly, and teleport across an interconnected series of landscapes, uncovering hidden shrines, old ruins, and strange characters.' FROM games WHERE igdb_id = 132631 ON CONFLICT (game_id, language_code) DO NOTHING;
