INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spellbreak', 'Spellbreak is an epic fantasy action-spellcasting game where players fight to become an all-powerful battlemage. Weave spectacular spell combinations, craft strategic builds, and master your environment as you dominate the Hollow Lands solo or with friends in a non-stop quest for survival. The servers are currently shut down, but the developers have generously released a PC standalone version that allows you to host community servers or play offline.' FROM games WHERE igdb_id = 112870 ON CONFLICT (game_id, language_code) DO NOTHING;
