INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crysis Remastered', 'With its 2007 release, Crysis set the industry standard for first person shooters with stunning visuals, highly evolved gameplay, and an enormous sandbox world. Crysis Remastered adds new graphic features, high-quality textures, and the CRYENGINE''s native hardware- and API-agnostic ray tracing solution to update the game for a new generation of hardware.' FROM games WHERE igdb_id = 132164 ON CONFLICT (game_id, language_code) DO NOTHING;
