INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hellpoint', 'Hellpoint is a dark sci fi action RPG set in the aftermath of a massive quantum cataclysm. Every living being quickly lost their mind as their memories and bodies were merged with alternate versions of themselves from parallel universes. The accident also attracted entities of immense power that should have been left alone, in the depth of other dimensions.' FROM games WHERE igdb_id = 36476 ON CONFLICT (game_id, language_code) DO NOTHING;
