INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moose Life', 'Moose Life is a trippy, psychedelic trance shooter. Created in the style of a 1980s arcade game, Moose Life offers you an exhilarating ride into the trance zone. Spectacular shooty action and a top techno soundtrack will raise your mood. If you have VR, immerse yourself for greater satisfaction.' FROM games WHERE igdb_id = 138332 ON CONFLICT (game_id, language_code) DO NOTHING;
