INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fantasy-friends', 138035, '2020-11-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hwh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ara22.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy Friends', 'Welcome to Fantasy Friends, a world of magic and fantasy where you''re responsible for taking care of fantastic creatures! The game takes place in a gorgeous fantasy forest where anything is possible! With the help of Aurea, the magic fairy, you will care for 12 adorable new pet friends. Take care of them and make sure you give them all the love they need. If you do, your pets will grow up and play with you. The more you care for them, keeping them happy and healthy, the more mana you will earn. Use your mana to get new creatures, buy them new clothes or even cooler toys to play with, and decorate the forest with incredible fun items. Features: From a flying panda to a rainbow unicorn, discover 12 incredible creatures you''ll love to cuddle and play with. As soon as they hatch, all of them will need your attention. Each animal needs a specific food you''ll have to produce. They each live in their own house and have an original game that they like best. Have fun while getting to know them all. Collect hundreds of colours and skins for your pets and challenge your friends to see who will have the most unique creatures. Be the first to find the rarest ones. Get cool accessories (hats, sunglasses, ribbons, etc.) to customise each of your pets. Decorate the forest in your own style with beautiful buildings, plants, and magical objects. Some of them may surprise you. Random magical events can happen at any time… You can earn more mana or even get exclusive skins.' FROM games WHERE igdb_id = 138035 ON CONFLICT (game_id, language_code) DO NOTHING;
