INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('superstar-woollim', 137874, '2020-04-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co698p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc11mor.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperStar Woollim', 'SuperStar Woollim is a rhythm game where your mission is to tap on music notes while you listen to a ton of different K-pop songs. The title includes music from tons of South Korean groups from the Woollim Entertainment record label. Among these, you''ll find INFINITE, Rphabet, Lovelyz and Golden Child. From the main menu in SuperStar Woollim you''ll be able to select one of the available artists to play the games with their profile. After this, you''ll be ready to follow the rhythm of each of the songs by tapping on the chords that appear on the screen at full speed. If you manage to be precise, at the end of the song you''ll be rewarded with cards that will reveal new singers and resources. Although to unlock some songs you''ll have to pay real money, you will find some songs that you can play for free. Plus, you''ll have a blast discovering all the Korean singers and groups that appear in the rewards boxes. The whole time, you''ll be competing against users from all around the world to complete each song with the best score possible. SuperStar Woollim lets you enjoy your favorite K-Pop music groups while you show off your ability to follow the beat of each song. The huge number of resources available to be unlocked also adds a little extra motivation to continue beating levels to collect all the cards available in the game.' FROM games WHERE igdb_id = 137874 ON CONFLICT (game_id, language_code) DO NOTHING;
