INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'In Silence', 'In Silence is a multiplayer horror game. One player takes on the role of the monster who has hypersensitive hearing abilities and is almost completely blind. The other players(2-6) play as survivors, trying to escape or hunting the monster.' FROM games WHERE igdb_id = 140038 ON CONFLICT (game_id, language_code) DO NOTHING;
