INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('betrayal-dot-io', 139300, '2020-10-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wn9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8m68.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Betrayal.io', 'Hi everyone! Thanks for all your patience, we are excited to announce the next (more open) alpha phase of Betrayal- an online multiplayer social deception/murder mystery game! We have been big fans of the genre for years now, and it''s been some of our dream to make an interactive, real-time version of Werewolf/Mafia/Town of Salem since the Zombs.io days. We are super happy to see the success of Among Us, which many of our team has been playing - and that has inspired us to finish our version and hopefully push the envelope on the whole social mystery genre! With that said, we welcome everyone in this discord to try the game and help give us feedback, suggestions, and more! We''ve been working on this for quite some time and I''m excited for everyone to try it out and let us know what you think!' FROM games WHERE igdb_id = 139300 ON CONFLICT (game_id, language_code) DO NOTHING;
