INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-well-speaks-to-me', 185731, '2020-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4aik.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf2jw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Well Speaks to Me', 'The Well Speaks To Me is a horror game where a definitely normal girl does chores, lives their daily life and gathers water from a well. You can''t stop her from going insane, but you can enjoy the ride. You live alone in the forest doing tasks to survive. Turn on the generator, chop the firewood, draw water from the well... But appearances are deceiving, and not everything is as innocent as it seems. Why don''t people really come to the forest? Was your family really killed in an accident? What is that thing outside the window? What really happened in the well? Some of these questions will be answered. Some of them won''t. But one thing''s for sure: something''s very wrong. And you''re running out of time.' FROM games WHERE igdb_id = 185731 ON CONFLICT (game_id, language_code) DO NOTHING;
