INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thermo Sudoku', 'How does Thermo Sudoku work? Well each sudoku grid contains thermometer shapes (often drawn to create themes) and digits on thermometers must increase as one moves further from the bulb end. The interactions between the thermometers leads to new logical ideas and patterns that completely refreshes the standard sudoku solving experience.' FROM games WHERE igdb_id = 153687 ON CONFLICT (game_id, language_code) DO NOTHING;
