INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyder', 'Set in a retro universe, British Spy Agency ‘EP-8’ has created Agent 8, the most sophisticated miniature robot spider on earth! Built using experimental technology, this itsy-bitsy superspy is equipped with all the gadgets and gizmos you’ll need; cut through panels, overload terminals, flip switches, and open valves as you scurry about sabotaging the heinous plans of evil doers.' FROM games WHERE igdb_id = 93470 ON CONFLICT (game_id, language_code) DO NOTHING;
