INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('freelancer-simulator-2', 135308, '2020-06-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2af8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8coa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freelancer Simulator 2', 'Game Description:  Create your own startup from scratch! Work at freelance, build your own games or applications, promote your projects and don''t forget about your character life! Play the original sequel to the series that once won the love of millions of players!  A unique gaming experience in the businessman life simulator. Complete the entire experience from scratch to billions of dollars. Beautiful graphic design, unique sound and interesting gameplay will plunge you headlong into the life of a freelancer!  Follow the market trends, develop or create new technologies in the Freelancer Simulator! Participate in ratings with other players and discover new achievements in the game!  Game Features:  - Create your games and applications;  - Develop your startup, find investments;  - Follow the mood and vital indicators of the hero;  - Upgrade your equipment and create new ones;  - Negotiate with customers or attend exhibitions!  - Play without the Internet!  The game is easily synchronized between devices. And when connected to the Internet, all game functions open. Or you can play offline!  Freelancer Simulator 2 — absolutely free game, but some game elements can be bought for real money. The in-app purchase feature is disabled in the device’s settings.  And in conclusion, we want to say a huge THANK YOU to everyone who plays Freelancer Simulator 2!' FROM games WHERE igdb_id = 135308 ON CONFLICT (game_id, language_code) DO NOTHING;
