INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('all-over', 132234, '2020-04-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29fw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arm5v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All Over', 'An indie Action RPG/adventure/puzzle Complete story-based quests, solve puzzles, use your sword and spells to fight and gain loot from monsters. Gather resources to build and craft potions and items. Fight legendary bosses. Key Features Quests - Dozens of story quests and side missions. Story - In your journey, you will reveal your true identity while helping NPCs & magical creatures with their evil ruler Puzzles - Solve mind-blowing puzzles as you travel to mysterious places Action - Cast powerful spells, equip your legendary weapon and armor to help you fight your battles. Loot & Items - Find gold, potions, magical items, and weapons to aid you on your quest. Monsters - Fight or help different monsters and NPCs in Abelon. Win to gain XP and treasures or try to escape and live to fight another day Resource gathering - Mining, woodcutting, herbs, and more... Night & Day - Go out at midnight with a torch or fight your way during the day. Abelon changes with time. Boss fights - Go into the depth of the dungeons and fight badass bosses. Level up - Gain XP and grow in strength Steam achievements - Growing list of steam achievements.' FROM games WHERE igdb_id = 132234 ON CONFLICT (game_id, language_code) DO NOTHING;
