INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fault-elder-orb', 77277, '2020-07-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co500b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkfj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fault: Elder Orb', 'At the intersection of colliding universes, you fight for the survival of your world. Become imbued with power from Aspects and equip yourself with Factions'' legendary gear in this next-gen, action-packed, third-person MOBA. Welcome to Fault: Elder Orb! Fault: Elder Orb is not like other MOBA games; Unlike the popular top-down model for MOBA''s, Fault: Elder Orb is a 3rd person game, meaning you are right in the middle of the action. Our game has the high octane feel of popular brawlers and third-person shooters while preserving the strategy and team play potentials in popular MOBA games. CHOOSE YOUR HERO Select your play style with many variations of hero’s; from a massive hammer-wielding soul collector to a space mage with control over interdimensional portals. Play games to unlock more heroes to add to your collection and master the battlefield of Fault: Elder Orb! GROW STRONG WITH FAVOR A unique gameplay element that separates Fault from other MOBAs is the introduction of a feats system, which allows a player to gain strength by achieving milestones during a match. ADAPT AND EVOLVE Fault: Elder Orb has many unique items to choose from that can sway the flow of battle. Collect gold from minion and hero kills and build your hero to handle any situation. MAP AND OBJECTIVES Fault: Elder Orb has an original map suited to tactical play with its verticality and well-planned out jungle paths. The jungle is full of creatures that when slain will increase your strength!' FROM games WHERE igdb_id = 77277 ON CONFLICT (game_id, language_code) DO NOTHING;
