INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nature-matters', 149299, '2020-04-16', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gxq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbs6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nature Matters', 'Set off on a puzzle-filled journey to save the planet and experience a compelling tale of friendship, sacrifice and redemption. In "Nature Matters" you take on a role of a little plant spirit. Without protection, surrounded by a city that grows up from everywhere, one day she realizes that she is completely alone and won''t be able to survive. The only solution is to find her caretaker - a little boy who has been caught up in a whirlwind of human weakness and convince him to take care of her again. During your journey, you will see different lands devastated by the destructive human influence. Solving the puzzles, with the sounds of relaxing music, you will have the opportunity to restore vegetation and colors in them. The unique graphic design will allow you to immerse yourself in a world that will remain in your memory for a long time. The "Nature Matters" project is a small contribution that the studio "Digital Melody" wants to make towards arousing social awareness of the threats that result from human neglect of the natural environment. As the creators say, if at least one person becomes more attentive to nature by experiencing this game, it will be a great joy for us. Game features: - logic puzzles - atmospheric music - elegant graphics - stirring story' FROM games WHERE igdb_id = 149299 ON CONFLICT (game_id, language_code) DO NOTHING;
