INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tales-of-crestoria', 109283, '2020-07-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bwz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar15p3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Crestoria', 'Live. Even if it''s a sin. Tales of Crestoria is an RPG designed for mobiles, presented to new players and series'' fans alike, and set in a fully-realized original world. The game stars Kanata, a boy bears the stain of a crime for which he can never atone. He and his fellow transgressors set off on a quest to defy the very rules of their world. More than 50 colorful characters from the likes of Kosuke Fujishima and Mutsumi Inomata are brought to life as beautiful 3D models, with smooth controls allowing for exhilarating battles. Enjoy exploring the world together with fellow transgressors and experience their struggles, growth and bond. A truly dramatic story where beliefs are worth risking everything for. All of this serves to tell the unforgettable story of Kanata and his close-knit band of criminals. Experience their adventure in the palm of your hand.' FROM games WHERE igdb_id = 109283 ON CONFLICT (game_id, language_code) DO NOTHING;
