INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paprium', 'It''s Paprium - the brawler you''ve been waiting for since the 90s! After more than 4 epic years of development, WaterMelon Games is proud to present its new 16-Bit game: PAPRIUM (code-name: "ProjectY"), a postapocalyptic, outrageous, street brawler. PAPRIUM has been crafted at WM''s Magical Game Factory using Investor’s votes and suggestions. PAPRIUM has been developed by a team driven by true passion and 16-Bit excellence.' FROM games WHERE igdb_id = 55107 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 55107 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
