INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hinge VR', 'Hinge is a VR horror that takes place in a nightmarish building filled with high-quality graphics and sound effects. The game creates an environment of suspense as you struggle for survival in an oppressive atmosphere of horror that chases you wherever you go. Every step is filled with fear, as the heart races in anticipation of the next ghoulish creature to face.' FROM games WHERE igdb_id = 141170 ON CONFLICT (game_id, language_code) DO NOTHING;
