INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Emberheart', 'Emberheart is a top down ARPG Hack and Slash in the likes of Diablo, Torchlight, Grim Dawn! It’s an indie title that focusses on new and exciting gameplay systems and unique end game gameplay while also going back to the roots of iconic games like Diablo 2 for inspiration.' FROM games WHERE igdb_id = 129760 ON CONFLICT (game_id, language_code) DO NOTHING;
