INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA 2K21: Mamba Forever Edition', 'NBA 2K21 is the latest title in the world-renowned, best-selling NBA 2K series, delivering an industry-leading sports video game experience. With extensive improvements upon its best-in-class graphics and gameplay, competitive and community online features, and deep, varied game modes, NBA 2K21 offers one-of-a-kind immersion into all facets of NBA basketball and culture - where Everything is Game. The NBA 2K21 Mamba Forever Edition includes the following digital items: - 100,000 Virtual Currency - 10,000 MyTEAM Points - 10 MyTEAM Tokens - 60 MyCAREER Skill Boosts - 30 Gatorade Boosts - 40 MyTEAM Promo Packs (10 at launch, then 3 per week) - Sapphire Damian Lillard and Zion Williamson MyTEAM cards - MyPLAYER Shoe Collection - MyPLAYER backpack - Kobe Bryant Digital Collection - 5 MyPLAYER Shoes - 3 MyPLAYER Jerseys - Black Mamba MyPLAYER Uniform - Rookie Lakers MyTEAM Jerseys - Black Mamba custom MyTEAM Jerseys - Sapphire Kobe MyTEAM Card (Evos to Ruby) - 5 MyTEAM Shoes (Incl. 1 Diamond)' FROM games WHERE igdb_id = 136398 ON CONFLICT (game_id, language_code) DO NOTHING;
