INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Half Past Fate', 'Half Past Fate is a romantic narrative-adventure game about three relationships that form either over the span of eight hours or eight years. Follow the adventures of six people who stumble their way through love and companionship in a hybrid 3D pixel-art world. Lead them through their daily struggles, quirky events, and life-changing decisions. Featuring a full cast of diverse characters with contrasting personalities, Half Past Fate takes you through intersecting stories over varying time spans that show how love can grow and develop in unexpected ways.' FROM games WHERE igdb_id = 116001 ON CONFLICT (game_id, language_code) DO NOTHING;
