INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost of Tsushima: Legends', 'Ghost of Tsushima: Legends is an online co-operative multiplayer experience inspired by Japanese folk tales and mythology. Choose from one of four classes – Samurai, Hunter, Ronin or Assassin – and play with friends or via online matchmaking in a series of two-player story missions or four-player wave-based survival missions.' FROM games WHERE igdb_id = 140042 ON CONFLICT (game_id, language_code) DO NOTHING;
