INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tracks: Toybox Edition', 'Tracks is a toy train set builder which gives you the tools to play without limits. Jump into an extensive sandbox and lay down tracks, create bridges and build worlds, then hop into the driver''s seat of your train in first person view. Play with boosters, create firework displays, compose tunes and so much more. Jump into the Ultimate Toy Sandbox Start with a pre-made environment, be it a modern lounge or a night time Winter wonderland, or jump into an entirely blank world canvas.' FROM games WHERE igdb_id = 139928 ON CONFLICT (game_id, language_code) DO NOTHING;
