INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Never Breakup', 'This is a two-player game where two players are connected by a rope and they need to work together to pass the level. The game includes both action and puzzle, challenge your skills and brain. It should be noted that no matter what the outcome is, don''t break up with your partner!' FROM games WHERE igdb_id = 107968 ON CONFLICT (game_id, language_code) DO NOTHING;
