INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('urban-flow', 137659, '2020-06-25', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2sxm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9mr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Urban Flow', 'Urban Flow is a game about the subtle beauty of city streets filled with cars moving in perfect harmony. But such order does not happen all by itself - the city needs YOU to control the traffic lights and to make sure everything goes smoothly. That means no crashes, no jams. Everything will run perfectly - as long as you stay focused! Immerse yourself in a beautiful, hand-crafted, low-poly world to discover the enormous satisfaction of watching the hundreds of tiny, colorful cars flowing through the streets – all while listening to the chill, urban music. Over 100 levels, each with its own busy intersection. You have one job: operate the lights and keep it safe.' FROM games WHERE igdb_id = 137659 ON CONFLICT (game_id, language_code) DO NOTHING;
